<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any

const aspectRatio = computed(() => {
  if (props.content.aspectRatio) {
    return props.content.aspectRatio.replace(':', '/')
  }
  return '16/9' // Default to 16:9 for video
})
</script>

<template>
  <div
    class="w-full overflow-hidden bg-surface-muted"
    :style="{
      'aspect-ratio': aspectRatio
    }"
  >
    <video
      :src="content.url"
      class="h-full w-full object-cover"
      :poster="content.url"
      preload="metadata"
    />
  </div>
</template>

<style scoped></style>
