<script setup lang="ts">
import { Howl } from 'howler'
import { Pause, Play } from 'lucide-vue-next'
import { computed, onUnmounted, ref } from 'vue'
import { getConfig } from '../runtime/config'
import { resolveToken } from '../runtime/token'
import { isApiOrigin } from '../utils/isApiOrigin'
import { AudioMessage } from './../classes/message'
enum AudioState {
  Initial,
  Loading,
  Loaded,
  Playing,
  Paused
}
const props = defineProps<{ message: AudioMessage }>()
const config = getConfig()
const state = ref<AudioState>(AudioState.Initial)
const howl = ref<Howl>()
const progress = ref<number>(0)
const container = ref<HTMLElement>()
const isIncoming = computed(() => props.message.isIncoming)

// DECORATIVE ONLY — these bars are NOT a rendering of the message's actual
// audio signal. A real waveform needs a network fetch + decodeAudioData per
// message before the bubble can even render, which is too expensive to pay
// for every audio bubble in a room. Instead we draw a bar pattern seeded
// from the message id, so a given message always draws the same pattern
// (stable across re-renders/reorders) without decoding anything. Treat this
// purely as an "this is audio" affordance, never as peak data.
const BAR_COUNT = 24
function seededRandom(seed: string) {
  let h = 0
  for (let i = 0; i < seed.length; i++) {
    h = (Math.imul(h, 31) + seed.charCodeAt(i)) | 0
  }
  let state = h >>> 0
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0
    return state / 4294967296
  }
}
const barHeightsPercent = computed(() => {
  const rand = seededRandom(props.message.id)
  return Array.from({ length: BAR_COUNT }, () => 25 + Math.round(rand() * 75))
})
const playedBarCount = computed(() =>
  Math.min(BAR_COUNT, Math.round((progress.value / 100) * BAR_COUNT))
)
// The in-flight WebAudio decode cannot be aborted on unmount, so onload /
// onloaderror can still fire afterwards. This flag lets those callbacks bail so
// they never resurrect playback or write to an orphaned component.
let isUnmounted = false
const step = () => {
  if (!howl.value) return
  progress.value = (howl.value.seek() / howl.value.duration()) * 100
  if (howl.value.playing()) {
    requestAnimationFrame(step)
  }
}
const handlePlayButtonClick = async () => {
  switch (state.value) {
    case AudioState.Initial: {
      // Resolve the token before constructing the Howl so an API-origin fetch
      // carries a freshly minted credential (config.token can be stale if the
      // host refreshed it out of band) rather than the last static value.
      // Enter Loading synchronously, before the await, so a second tap during
      // token resolution can't re-enter case Initial and build a second Howl.
      state.value = AudioState.Loading
      const token = await resolveToken()
      const sound = new Howl({
        src: props.message.url,
        format: ['m4a', 'mp3', 'wav', 'aac', 'webm'],
        onload: () => {
          if (isUnmounted) return
          sound.play()
          state.value = AudioState.Playing
        },
        onplay: () => {
          requestAnimationFrame(step)
        },
        onend: () => {
          state.value = AudioState.Loaded
        },
        onloaderror: (_id, error) => {
          if (isUnmounted) return
          // Without a reset the switch has no Loading case, so the play button
          // spins forever. Reset to Initial so the user can retry, and unload
          // the failed instance (a retry creates a fresh Howl).
          console.error(error)
          sound.unload()
          howl.value = undefined
          state.value = AudioState.Initial
        },
        ...(isApiOrigin(props.message.url)
          ? {
              xhr: {
                headers: {
                  'IM-Authorization': token,
                  'IM-Client-Key': config.clientKey
                }
              }
            }
          : {})
      })
      howl.value = sound
      break
    }
    case AudioState.Loaded:
    case AudioState.Paused:
      howl.value?.play()
      state.value = AudioState.Playing
      break
    case AudioState.Playing:
      howl.value?.pause()
      state.value = AudioState.Paused
      break
    default:
      break
  }
}
const handleProgressClick = async (event: MouseEvent) => {
  if (!howl.value) return
  if (!container.value) return
  const { x, width } = container.value.getBoundingClientRect()
  progress.value = ((event.clientX - x) / width) * 100
  howl.value.seek((howl.value.duration() * progress.value) / 100)
}
onUnmounted(() => {
  // Stop playback and free the Howl so audio does not keep playing after the
  // cell is gone; step()'s `if (!howl.value) return` then ends the rAF loop.
  // isUnmounted also makes a late onload/onloaderror callback a no-op.
  isUnmounted = true
  howl.value?.unload()
  howl.value = undefined
})
</script>

<template>
  <div
    ref="container"
    data-testid="audio-message-container"
    class="relative flex w-full items-center gap-2 p-1"
    @click="handleProgressClick"
  >
    <!-- Filled accent circle, not a bare outline glyph — `fill="currentColor"`
         plus lucide's round stroke joins gives the triangle a soft edge
         instead of a hand-drawn sharp one. White always reads on `bg-accent`
         (see the white-on-accent contract in src/style.css /
         tests/tokenContrast.test.ts), so this button needs no per-bubble
         colour logic even though it sits on two different bubble grounds. -->
    <button
      class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-accent text-white"
      @click.stop="handlePlayButtonClick"
    >
      <template
        v-if="
          new Set([
            AudioState.Initial,
            AudioState.Loaded,
            AudioState.Paused
          ]).has(state)
        "
      >
        <Play :size="16" class="ml-0.5" fill="currentColor" />
      </template>
      <div
        v-else-if="state === AudioState.Loading"
        class="flex h-5 w-5 items-center justify-center"
      >
        <!-- Same track/arc split as before, but now on a solid `bg-accent`
             fill rather than the themed bubble, so both halves are `white`
             (always legible on accent, see the white-on-accent contract)
             instead of the bubble-aware token pair this replaced. -->
        <svg
          class="h-4 w-4 animate-spin fill-white text-white/40"
          viewBox="0 0 100 101"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z"
            fill="currentColor"
          />
          <path
            d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z"
            fill="currentFill"
          />
        </svg>
      </div>
      <template v-else-if="state === AudioState.Playing">
        <Pause :size="16" fill="currentColor" />
      </template>
    </button>
    <!--
      Decorative bar pattern (see the comment on `barHeightsPercent` in
      <script>) standing in for a real waveform. Played bars use
      `accent-vivid` — already proven as a foreground role against BOTH
      bubble grounds across supported palettes and colour modes by the loading-spinner comment
      this replaced (5.33-7.29:1 range).

      Unplayed bars are `currentColor` (the bubble's own already-audited
      text token — `content` incoming, `message-own-content` outgoing) at a
      fixed opacity, NOT the `border` divider token: `border` measured well
      under 3:1 against `message-own` (the light-blue outgoing bubble) even
      though it read fine against `message`, because the two bubbles are
      genuinely different grounds and one token cannot satisfy both without
      either overshooting the incoming bubble or undershooting the outgoing
      one. The opacity is therefore PER-VARIANT rather than a single
      compromise value — `opacity-50` incoming, `opacity-60` outgoing —
      chosen so each clears >=3:1 (WCAG 1.4.11) against its own ground in
      the audited palette and colour-mode combinations without darkening the incoming
      bars past what already worked there. See the AudioMessageContent
      contrast note in this file's test for the measured numbers.
    -->
    <div class="flex h-6 min-w-0 flex-1 items-center gap-0.5">
      <div
        v-for="(barHeight, index) in barHeightsPercent"
        :key="index"
        class="min-h-0.5! w-0.5 shrink-0 rounded-sm"
        :class="[
          index < playedBarCount
            ? 'bg-accent-vivid'
            : ['bg-current', isIncoming ? 'opacity-50' : 'opacity-60']
        ]"
        :style="{ height: `${barHeight}%` }"
      />
    </div>
    <!-- Plain text, not a pill: inherits the bubble's own text colour
         (`text-content` incoming / `text-message-own-content` outgoing, set
         by MessageCell.vue on the wrapping element) via `currentColor`,
         dimmed with opacity rather than a second colour so it always
         matches whichever bubble it renders on. -->
    <div class="shrink-0 text-xs font-semibold text-current opacity-70">
      {{ Math.floor(message.duration / 60) }}:{{
        `${Math.floor(message.duration % 60)}`.padStart(2, '0')
      }}
    </div>
  </div>
</template>

