<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import RoomListWrapperCell from './RoomListWrapperCell.vue'
import { useElementSize } from '@vueuse/core'
import dayjs from 'dayjs'
import { MessagesSquare, Search, X } from 'lucide-vue-next'
import { Virtualizer } from 'virtua/vue'
import { useI18n } from 'vue-i18n'
import { useVfm } from 'vue-final-modal'
import Folder from '../classes/folder'
import Room from '../classes/room'
import RoomListHeading from '../classes/roomListHeading'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { useRoomSearch } from '../composables/useRoomSearch'
import { useRoomSort } from '../composables/useRoomSort'
import { useViewportHeight } from '../composables/useViewportHeight'
import { SearchType } from '../enums/searchType'
import { getConfig } from '../runtime/config'
import { getSocket } from '../runtime/socket'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import Settings from './../classes/settings'
import ManageFoldersModal from './folders/ManageFoldersModal.vue'
import UpdateFolderModal from './folders/UpdateFolderModal.vue'
import HeaderDivider from './HeaderDivider.vue'
import MassTextingModal from './MassTextingModal.vue'
import RoomListToolbar from './RoomListToolbar.vue'
import LoadingSvg from './svgs/LoadingSvg.vue'

const imkit = useImkitStore()
const vfm = useVfm()
const config = getConfig()

// Sort
const { sortType, isFirstLoading, setSortType } = useRoomSort()

const sortedRooms = computed((): Room[] => imkit.sortedRooms)
const sortedFolders = computed(() =>
  imkit.sortedFolderIds
    .map((id: string) => imkit.folders[id])
    .filter((folder: Folder) => folder)
)
const selectedFolder = computed(() => {
  return imkit.folders[imkit.selectedFolderId]
})
const searchType = computed((): SearchType => {
  return imkit.searchType
})
const searchTypes = computed(() => {
  if (imkit.searchKeyword) {
    return Object.values(SearchType).filter((t) => t in imkit.searchRooms) // preserve SearchType enum order
  }
  return []
})
const roomTag = computed(() => {
  return imkit.roomTag
})
const settings = computed((): Settings => config.settings)

// The room-list search field raises the same software keyboard the composer
// does, so this surface needs the same two halves ChatRoom gets (issue #20):
// publish the measured viewport height, and — when the host says its shell
// owns the whole page — pin the document.
//
// It is not enough for ChatRoom alone to do this. On the agent dashboard
// <imkit-chat-room> is only rendered once a room is selected, so the mobile
// room-list view had NEITHER: `--imkit-viewport-height` fell back to `100dvh`
// (the host shell sizes off it) and nothing held the page at the top, which is
// exactly the blank-band bug `fullPageEnabled` exists to fix. Both calls are
// refcounted, so a mount that already tracks costs no extra listeners.
useViewportHeight({ lockScroll: () => settings.value.fullPageEnabled === true })

const uid = computed(() => getUid())

let visibilityHiddenAt = 0
let stopUidWatch: (() => void) | null = null
let lastUid = ''

const fetchTask = async () => {
  isFirstLoading.value = true
  try {
    await imkit.fetchPrefs()
    await imkit.fetchRooms()
  } finally {
    isFirstLoading.value = false
  }
  await imkit.fetchRoomsInFolders()
}

// Search
const {
  searchKeyword,
  searchInput,
  isCompositting,
  isAPIRequesting,
  clearSearch
} = useRoomSearch({ fetchTask })

const list = computed<(Room | Folder | RoomListHeading)[]>(() => {
  if (imkit.searchKeyword && vfm.modals.length === 0) {
    if (
      searchType.value === SearchType.RoomPrefFolder &&
      selectedFolder.value
    ) {
      const list = [...(imkit.searchRooms[searchType.value] || [])] as Array<
        Room | Folder
      >
      const roomsInSelectedFolder = selectedFolder.value.roomIds
        .map((id: string) => imkit.rooms[id])
        .filter((room): room is Room => {
          if (roomTag.value) {
            return room && room.roomTags.includes(roomTag.value)
          }
          return !!room
        })
      const index = list.findIndex(
        (item) => item.id === selectedFolder.value.id
      )
      if (index > -1) {
        list.splice(index + 1, 0, ...roomsInSelectedFolder)
      }
      return list.filter((item): item is Room => item instanceof Room)
    }
    const searchResults = imkit.searchRooms[searchType.value] || []
    return searchResults
  }
  // The 「資料夾」/「對話」 headings are interleaved directly into the
  // virtualised list (rather than living in the fixed, non-scrolling header
  // above it) so they scroll with the rows they label. Both appear as soon
  // as ONE folder exists — no count threshold, per the reference's own
  // annotation: a conditional interface reads as the feature having
  // disappeared, and a heading popping in partway through (e.g. on the
  // third folder) reads as a bug.
  const hasFolders = sortedFolders.value.length > 0
  const list: Array<Room | Folder | RoomListHeading> = []
  if (hasFolders) {
    list.push(new RoomListHeading('folders'))
  }
  list.push(...sortedFolders.value)
  if (hasFolders) {
    list.push(new RoomListHeading('conversations'))
  }
  list.push(...sortedRooms.value)
  if (selectedFolder.value) {
    const roomsInSelectedFolder = imkit.roomsInSelectedFolder
    const folderIndex = sortedFolders.value.findIndex(
      (folder: Folder) => folder.id === selectedFolder.value.id
    )
    if (folderIndex > -1) {
      // `folderIndex` is an index into `sortedFolders`, not into `list` — it
      // needs the leading 「資料夾」 heading's offset added back in, or the
      // expansion lands one row too early once headings are present.
      const index = folderIndex + (hasFolders ? 1 : 0)
      list.splice(index + 1, 0, ...roomsInSelectedFolder)
    }
  }
  return list
})

const isRequesting = computed(
  () =>
    vfm.modals.length === 0 &&
    (isCompositting.value ||
      isFirstLoading.value ||
      (isAPIRequesting.value && searchKeyword.value.length > 0))
)

// Template v-if visibility variables
const showClearSearchButton = computed(() => !!searchKeyword.value)
// The `list.length === 0` half alone was not enough. `fetchTask` awaits
// fetchPrefs() and then fetchRooms(); the first sets the FOLDERS and returns
// quickly, the second sets the ROOMS and does not. In that window
// isFirstLoading is still true, but the list is already non-empty (folders
// heading + folders + conversations heading), so the skeleton switched off
// and the real list rendered with nothing at all under 「對話」 — reported as
// a stretch of blank below the folders.
//
// So first load shows the skeleton unconditionally: the two sections come
// from two independent fetches and there is no moment where showing half of
// them is useful. The length check stays for the OTHER caller of
// isRequesting — an in-list search, where replacing an already-populated
// list with a skeleton would be wrong.
const showLoadingSkeleton = computed(
  () =>
    (isFirstLoading.value && vfm.modals.length === 0) ||
    (isRequesting.value && list.value.length === 0)
)
const showSearchTypeTabs = computed(
  () => searchTypes.value.length > 0 && vfm.modals.length === 0
)
const showEmptyState = computed(
  () =>
    !isRequesting.value && list.value.length === 0 && vfm.modals.length === 0
)
const showCustomNoRoomsImage = computed(() => !!settings.value.noRoomsImageURL)
const showDefaultNoRoomsImage = computed(
  () => settings.value.noRoomsImageURL === undefined
)
const showNoRoomsText = computed(
  () => !!settings.value.noRoomsText || settings.value.noRoomsText === undefined
)
// Aliased, not the usual `const { t }`: this file's search-type tab `v-for`
// already binds `t` (see the tabs block in the template), and two different
// `t`s in one component is a trap for whoever edits it next.
const { t: translate } = useI18n()
// Same condition as `list`'s search branch above, deliberately duplicated
// rather than approximated: if the two ever disagree, the empty state
// describes a list that a different branch produced.
//
// Without this the empty state said "no chat rooms available" for a search that
// simply matched nothing, which is a lie — the rooms exist, they are filtered.
// It also contradicted the chat column next to it, which correctly went on
// telling the user to pick one.
const isSearchEmptyState = computed(
  () => !!imkit.searchKeyword && vfm.modals.length === 0
)
// `settings.noRoomsText` is a host override for "this user has no chat rooms".
// It is not an answer for "your search matched nothing", so the search copy
// ignores it. The `''`-means-suppress contract still holds via showNoRoomsText:
// a host that hid the empty state keeps it hidden in both cases.
const emptyStateText = computed(() => {
  if (isSearchEmptyState.value) return translate('noRoomsMatchSearch')
  return settings.value.noRoomsText === undefined
    ? translate('noRoomsAvailable')
    : settings.value.noRoomsText
})

const scrollEl = ref<HTMLElement>()
const headerEl = ref<HTMLElement>()
const { height: headerH } = useElementSize(headerEl)

const BOTTOM_THRESHOLD = 100
let wasAtBottomEdge = false

const tobottom = () => {
  imkit.fetchRooms()
}

const onRoomListScroll = (offset: number) => {
  const el = scrollEl.value
  if (!el) return
  const atEdge = offset + el.clientHeight >= el.scrollHeight - BOTTOM_THRESHOLD
  if (atEdge && !wasAtBottomEdge) tobottom()
  wasAtBottomEdge = atEdge
}
const createFolder = () => {
  const { open } = useModal({
    component: UpdateFolderModal
  })
  open()
}
const manageFolders = () => {
  const { open } = useModal({
    component: ManageFoldersModal
  })
  open()
}
const massTexting = () => {
  const { open } = useModal({
    component: MassTextingModal
  })
  open()
}

watch(sortedRooms, (rooms) => {
  if (rooms.length === 0) return
  if (!settings.value.autoSelectRoomWhenLoaded) return
  if (!imkit.selectedRoomId && document.body.clientWidth > 640) {
    if (settings.value.enableReadReceipt) {
      const room = Object.values(rooms).find(
        (room) => room.numberOfUnread === 0
      )
      if (room) {
        imkit.$patch({ selectedRoomId: room.id })
      }
    } else {
      const room = rooms[0]
      if (room) {
        imkit.$patch({ selectedRoomId: room.id })
      }
    }
  }
})

const onVisibilityChange = () => {
  if (document.hidden) {
    visibilityHiddenAt = dayjs().unix()
  } else {
    const hiddenInterval = dayjs().unix() - visibilityHiddenAt
    if (hiddenInterval > 60) {
      fetchTask()
      getSocket().connect()
    }
  }
}

onMounted(() => {
  stopUidWatch = watch(
    uid,
    () => {
      if (uid.value === lastUid) return
      lastUid = uid.value
      fetchTask()
    },
    { immediate: true }
  )
  document.addEventListener('visibilitychange', onVisibilityChange)
})

onUnmounted(() => {
  if (stopUidWatch) {
    stopUidWatch()
    stopUidWatch = null
  }
  document.removeEventListener('visibilitychange', onVisibilityChange)
})
</script>

<template>
  <!-- <div class="flex flex-col w-1/3 h-full overflow-auto p-2 gap-1">
    <room-list-wrapper-cell
      v-for="item in list"
      :key="item.id"
      :source="item"
    />
  </div> -->
  <div class="relative h-full">
    <div
      ref="scrollEl"
      class="h-full overflow-auto transition ease-in-out"
      style="overflow-anchor: none"
    >
      <div ref="headerEl">
        <RoomListToolbar
          :sort-type="sortType"
          :show-dark-mode-switch="settings.showDarkModeSwitch"
          :mass-texting-enabled="settings.massTextingEnabled"
          @sort="setSortType"
          @create-folder="createFolder"
          @mass-texting="massTexting"
        />
        <div class="relative flex h-18 items-center px-4">
          <!-- Overlaid border, not a real `border-b` — see HeaderDivider.vue. -->
          <HeaderDivider />
          <div class="flex w-full items-center space-x-2">
            <div class="relative flex-1">
              <div
                class="absolute top-1/2 left-3 flex h-4.5 w-4.5 -translate-y-1/2 transform items-center justify-center"
              >
                <LoadingSvg v-if="isRequesting" />
                <Search v-else class="h-4.5 w-4.5 text-content-subtle" />
              </div>
              <input
                ref="searchInput"
                v-model="searchKeyword"
                data-testid="room-search-input"
                :aria-label="$t('search')"
                class="flex h-11 w-full rounded-full bg-field px-3 py-2 pt-2 pr-10 pl-10 text-base! text-content file:border-0 file:bg-transparent file:text-base file:font-medium placeholder:text-content-subtle focus-visible:ring-1 focus-visible:ring-accent-vivid focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50 md:text-base"
                :placeholder="settings.searchRoomPlaceholder || $t('search')"
                @compositionstart="isCompositting = true"
                @compositionend="isCompositting = false"
                @blur="isCompositting = false"
              />
              <button
                v-if="showClearSearchButton"
                class="absolute inset-y-0 right-3 flex items-center text-content-muted transition-colors hover:text-content focus-visible:ring-1 focus-visible:ring-accent-vivid focus-visible:outline-none"
                type="button"
                :aria-label="$t('clearSearch')"
                @click="clearSearch"
              >
                <X class="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
        <div
          v-if="showSearchTypeTabs"
          class="mx-2 mt-2 mb-2 flex items-center gap-2 overflow-auto text-base text-content"
        >
          <div
            v-for="t in searchTypes"
            :key="t"
            class="cursor-pointer rounded-lg px-3 py-2 whitespace-nowrap hover:bg-surface-hover"
            :class="{
              'bg-surface-muted font-medium text-content': t === searchType
            }"
            @click="
              imkit.$patch({
                searchType: t
              })
            "
          >
            {{ $t(t) }}
          </div>
        </div>
        <!--
          Geometry mirrors RoomCell, so the skeleton does not resize when real
          rows replace it. A row there is `gap-3 px-4 py-2.5` around a 50px
          avatar — 70px, which is also the Virtualizer's `:item-size`. This
          block used `gap-1` on the column and `p-2` on the row: 66px plus a
          4px gap, so every skeleton row sat 4px off the row it stood in for
          and the whole list shifted on load. No gap between rows either —
          list rows are full-bleed and separated by their own padding.
        -->
        <div v-if="showLoadingSkeleton" class="flex flex-col">
          <div v-for="i in 20" :key="i" class="flex gap-3 px-4 py-2.5">
            <div class="loading h-[50px] w-[50px] rounded-lg bg-surface" />
            <div class="flex grow flex-col justify-center gap-2">
              <div class="loading h-5 w-full rounded-md bg-surface" />
              <div class="loading h-4 w-4/5 rounded-md bg-surface" />
            </div>
          </div>
        </div>
        <div
          v-else-if="showEmptyState"
          class="flex h-[80dvh] flex-col items-center justify-center gap-4 px-6 py-12"
        >
          <img
            v-if="showCustomNoRoomsImage"
            :src="settings.noRoomsImageURL"
            class="h-24 w-24 object-contain"
          />
          <!--
            Was `assets/imkit_logo_no_text.png` — the IMKit logo, in IMKit
            blue. Wrong twice over in a white-label SDK: it puts the vendor's
            identity inside the customer's product, and a raster cannot follow
            the palette. A host could already override it via
            `noRoomsImageURL`, but a default every host must override is the
            wrong default.

            Same glyph, size and colour as MainView's no-room-selected state.
            The two can be on screen together, so they have to read as one
            voice rather than two near-misses.

            `content-subtle`, not `content-faint`, so the mark matches the
            paragraph below it.
          -->
          <MessagesSquare
            v-else-if="showDefaultNoRoomsImage"
            class="h-14 w-14 text-content-subtle"
            :stroke-width="1.25"
            aria-hidden="true"
          />
          <p
            v-if="showNoRoomsText"
            class="text-center text-base text-content-subtle"
          >
            {{ emptyStateText }}
          </p>
        </div>
      </div>
      <Virtualizer
        :data="list"
        :scroll-ref="scrollEl"
        :start-margin="headerH"
        :item-size="70"
        @scroll="onRoomListScroll"
      >
        <template #default="{ item }">
          <RoomListWrapperCell :source="item" @manage-folders="manageFolders" />
        </template>
      </Virtualizer>
    </div>
  </div>
</template>

<style scoped>
@keyframes bg {
  /* Was `oklch(0.872 0.01 258.338)` (= #d1d5dc) with a note saying no token
   * matched, because --color-border-strong was gray-300 in light and zinc-600
   * in dark so adopting it would have shifted the dark value. Two things have
   * changed since: the palette is seed-derived, and border-strong resolves to
   * #7d848b in light — dE 30.4 from that literal, so the note's premise no
   * longer holds either way. The dark half of this animation is a SEPARATE
   * keyframe (bg-dark, below), so a token chosen here cannot reach it.
   *
   * --color-border is the closest remaining token (dE 10.4 from the literal)
   * and keeps the pulse amplitude the literal had: dE 10.0 against the
   * --color-surface-muted trough, versus 12.9 before. The point of the change
   * is that a hardcoded literal could not follow the palette at all. */
  0% {
    background-color: var(--color-border);
  }
  50% {
    background-color: var(--color-surface-muted);
  }
  100% {
    background-color: var(--color-border);
  }
}

@keyframes bg-dark {
  0% {
    /* Was a raw zinc-700 literal, hue-neutral against every dark preset. That
     * read as plain grey against the redesign's blue-tinted dark surfaces
     * (--color-surface #0f2038 / --color-panel #0b1a2e) — a reviewer flagged
     * it directly, same complaint as the highlight-token clash --color-highlight
     * above resolved. --color-content-faint is already blue-grey (hue ~264,
     * the same family as --color-border/--color-content-muted) and already
     * contrast-tuned per preset, so reusing it here (as a background swatch,
     * not its usual text role) needs no new token. Measured against this
     * animation's own backdrop — the room-list scroll container, which sits
     * on --color-panel/--color-surface, not a message bubble — it clears the
     * 3:1 content-shape floor in both dark presets: 3.61:1 (blue panel
     * #0b1a2e), 3.38:1 (blue surface #0f2038), 3.94:1 (neutral panel
     * #0e1013), 3.71:1 (neutral surface #15171c). */
    background-color: var(--color-content-faint);
  }
  50% {
    background-color: var(--color-surface-muted);
  }
  100% {
    background-color: var(--color-content-faint);
  }
}

.dark .loading {
  animation: bg-dark 2s infinite;
}
.loading {
  animation: bg 2s infinite;
}
</style>
