import { computed, ref } from 'vue'
import type ChatRoomContent from '../classes/chatRoomContent'
import type Message from '../classes/message'
import { useImkitStore } from '../stores/imkit'
import {
  getChatRoomContentMediaTime,
  indexRoomMedia,
  sortChatRoomContentMedia
} from '../utils/chatRoomContent'
import {
  collectRoomMediaItems,
  getRoomMediaFileId
} from '../utils/roomMediaList'

export function useRoomContentMediaNavigation(
  getRoomId: () => string | undefined,
  getAdditionalMessages: () => readonly Message[] = () => [],
  collection: 'Media' | 'Preview' = 'Media'
) {
  const imkit = useImkitStore()
  const stateKey = `chatRoomContent${collection}` as const
  const collectionRoomId = computed(() => imkit[`${stateKey}RoomId`])
  const collectionOffset = computed(() => imkit[`${stateKey}Offset`])
  const collectionHasMore = computed(() => imkit[`${stateKey}HasMore`])
  const loadMore = (roomId: string) =>
    collection === 'Preview'
      ? imkit.fetchRoomContentPreview({ roomId, loadMore: true })
      : imkit.fetchRoomContentMedia({ roomId, loadMore: true })
  // Both collections page newest first. Lightbox arrows retain chronological
  // direction, so older pages are loaded at the left boundary.
  const pageStep = -1
  const selectedMediaId = ref<string | null>(null)
  let selectionGeneration = 0
  let nextNavigationRequest: {
    key: string
    promise: Promise<void>
  } | null = null

  const messageMedia = computed(() => {
    const roomId = getRoomId()
    if (!roomId) return []
    const messages = new Map<string, Message>()
    const lists = imkit.messageMultiLists?.get(roomId)
    let segment = lists?.head ?? lists?.main
    while (segment) {
      for (const message of segment.array()) messages.set(message.id, message)
      segment = segment.next
    }
    for (const message of getAdditionalMessages()) {
      if (message.roomId === roomId) messages.set(message.id, message)
    }
    return collectRoomMediaItems([...messages.values()])
  })
  const messageMediaIndex = computed(() => indexRoomMedia(messageMedia.value))
  const getMediaCreatedAt = (media: ChatRoomContent) =>
    media.messageCreatedAt
      ? getChatRoomContentMediaTime(media)
      : (messageMediaIndex.value.get(media._id)?.createdAt ??
        getChatRoomContentMediaTime(media))

  const orderedMedia = computed(() => {
    const roomId = getRoomId()
    if (!roomId || collectionRoomId.value !== roomId) return []
    return sortChatRoomContentMedia(
      imkit[stateKey].filter(
        (item) =>
          collection === 'Media' ||
          item.fileType === 'image' ||
          item.fileType === 'video'
      ),
      messageMedia.value
    )
  })
  const sortNewestFirst = (media: readonly ChatRoomContent[]) =>
    sortChatRoomContentMedia(media, messageMedia.value, 'desc')
  const newestFirstMedia = computed(() => sortNewestFirst(orderedMedia.value))
  // Right/next advances through each message, then newer messages.
  // Left/previous retraces that sequence, independent of gallery group order.
  const selectedMediaIndex = computed(() =>
    orderedMedia.value.findIndex((item) => item._id === selectedMediaId.value)
  )
  const selectedMedia = computed(
    () => orderedMedia.value[selectedMediaIndex.value] ?? null
  )
  const mediaCount = computed(() => {
    const roomId = getRoomId()
    if (!roomId || collectionRoomId.value !== roomId) {
      return orderedMedia.value.length
    }
    return Math.max(
      orderedMedia.value.length,
      collection === 'Media'
        ? imkit.chatRoomContentMediaTotalCount
        : orderedMedia.value.length + (collectionHasMore.value ? 1 : 0)
    )
  })
  const canNavigateNext = computed(() => {
    const roomId = getRoomId()
    const index = selectedMediaIndex.value
    if (index < 0) return false
    if (index < orderedMedia.value.length - 1) return true
    return (
      Boolean(roomId) &&
      collectionRoomId.value === roomId &&
      collectionHasMore.value &&
      selectedMessageMedia.value.some(
        (item, index) =>
          index >
            selectedMessageMedia.value.findIndex(
              (selected) =>
                getRoomMediaFileId(selected) === selectedMediaId.value
            ) &&
          !orderedMedia.value.some(
            (loaded) => loaded._id === getRoomMediaFileId(item)
          )
      )
    )
  })
  const mediaForMessage = (fileId: string | null) => {
    const selected = messageMedia.value.find(
      (item) => getRoomMediaFileId(item) === fileId
    )
    return selected
      ? messageMedia.value.filter(
          (item) => item.messageId === selected.messageId
        )
      : []
  }
  const selectedMessageMedia = computed(() =>
    mediaForMessage(selectedMediaId.value)
  )
  const canNavigatePrevious = computed(
    () =>
      selectedMediaIndex.value > 0 ||
      (selectedMediaIndex.value >= 0 &&
        collectionHasMore.value &&
        collectionRoomId.value === getRoomId())
  )

  const hasMissingMessageMedia = (fileId: string | null) => {
    const availableIds = new Set(orderedMedia.value.map((item) => item._id))
    return mediaForMessage(fileId).some((item) => {
      const id = getRoomMediaFileId(item)
      return id !== null && !availableIds.has(id)
    })
  }
  const needsMessagePage = (fileId = selectedMediaId.value) =>
    collectionHasMore.value && hasMissingMessageMedia(fileId)

  // File pagination can split a group at any upload, including an image that
  // belongs BEFORE the clicked image. Complete that group before either arrow.
  const loadMessageMedia = async (fileId = selectedMediaId.value) => {
    const roomId = getRoomId()
    const generation = selectionGeneration
    const sessionEpoch = imkit.sessionEpoch
    if (!roomId) return false
    while (needsMessagePage(fileId)) {
      const offset = collectionOffset.value
      await loadMore(roomId)
      if (
        getRoomId() !== roomId ||
        collectionRoomId.value !== roomId ||
        selectionGeneration !== generation ||
        imkit.sessionEpoch !== sessionEpoch
      )
        return false
      if (collectionOffset.value <= offset) return false
    }
    return true
  }

  const selectMedia = (media: ChatRoomContent | null) => {
    selectionGeneration += 1
    selectedMediaId.value = media?._id ?? null
  }

  const selectAdjacentMedia = async (step: -1 | 1) => {
    let next = orderedMedia.value[selectedMediaIndex.value + step]
    while (next && needsMessagePage(next._id)) {
      if (!(await loadMessageMedia(next._id))) return
      next = orderedMedia.value[selectedMediaIndex.value + step]
    }
    if (next) selectMedia(next)
  }

  const navigate = async (step: -1 | 1) => {
    const roomId = getRoomId()
    if (!roomId || selectedMediaIndex.value < 0) return
    if (needsMessagePage() && !(await loadMessageMedia())) return
    if (orderedMedia.value[selectedMediaIndex.value + step]) {
      await selectAdjacentMedia(step)
      return
    }
    if (step !== pageStep) return

    const currentId = selectedMediaId.value
    const currentGeneration = selectionGeneration
    const currentSessionEpoch = imkit.sessionEpoch
    // A mixed preview page may contain only documents. Continue until there
    // is an adjacent image/video, or the API reaches the end of the room.
    while (collectionHasMore.value) {
      const offset = collectionOffset.value
      await loadMore(roomId)
      if (
        getRoomId() !== roomId ||
        collectionRoomId.value !== roomId ||
        selectedMediaId.value !== currentId ||
        selectionGeneration !== currentGeneration ||
        imkit.sessionEpoch !== currentSessionEpoch
      )
        return
      if (orderedMedia.value[selectedMediaIndex.value + step]) {
        await selectAdjacentMedia(step)
        return
      }
      if (collectionOffset.value <= offset) return
    }
  }

  const navigateOnce = (step: -1 | 1) => {
    const key = `${getRoomId() ?? ''}:${selectionGeneration}:${step}`
    if (nextNavigationRequest?.key === key) {
      return nextNavigationRequest.promise
    }
    const request = { key, promise: Promise.resolve() }
    request.promise = navigate(step).finally(() => {
      if (nextNavigationRequest === request) nextNavigationRequest = null
    })
    nextNavigationRequest = request
    return request.promise
  }
  const nextMedia = () => navigateOnce(1)
  const previousMedia = () => navigateOnce(-1)

  return {
    orderedMedia,
    newestFirstMedia,
    sortNewestFirst,
    getMediaCreatedAt,
    selectedMedia,
    selectedMediaIndex,
    mediaCount,
    canNavigateNext,
    canNavigatePrevious,
    selectMedia,
    nextMedia,
    previousMedia
  }
}
