<script setup lang="ts">
import { computed } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import IMImage from '../classes/image'
import { useRoomMediaLightbox } from '../composables/useRoomMediaLightbox'
import { useImkitStore } from '../stores/imkit'
import { ImageMessage, MessageStatus } from './../classes/message'
import { calculateImageSize } from './../utils/image-size'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
import MediaImg from './ui/MediaImg.vue'
const props = defineProps<{ message: ImageMessage }>()
const imkit = useImkitStore()
const uploadProgresses = computed(() => imkit.uploadProgresses)

// Lightbox state
const {
  open: lightboxOpen,
  mediaIndex: lightboxIndex,
  mediaItems: previewMediaItems,
  activeMediaItem,
  selectedMedia,
  mediaCount,
  canNavigatePrevious,
  canNavigateNext,
  openMessageMedia,
  previousMedia,
  nextMedia,
  close: closeLightbox
} = useRoomMediaLightbox(() => props.message)
const selectedImage = computed(() => {
  return activeMediaItem.value?.kind === 'image'
    ? activeMediaItem.value.image
    : null
})

const calculateSize = (index: number, image: IMImage) =>
  calculateImageSize(index, image, props.message.images.length)

const showImage = (imageIndex: number) => {
  openMessageMedia(
    (item) => item.kind === 'image' && item.imageIndex === imageIndex
  )
}
</script>

<template>
  <!-- No per-cell `rounded-lg`: individual images stay square-cornered and
       let the bubble's own `overflow-hidden` (MessageCell.vue) clip only the
       four OUTER corners, so the grid reads as one rounded block instead of
       each cell showing a rounded notch at the internal junctions. Same
       precedent as MixedMessageContent.vue:308 — the bubble owns the
       corner radius, media inside it stays square. -->
  <div
    class="grid gap-px"
    :class="[message.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1']"
  >
    <div
      v-for="(image, index) in message.images"
      :key="image.thumbnailUrl"
      class="relative flex items-center justify-center overflow-hidden"
      :class="{
        'col-span-2':
          message.images.length > 1 &&
          index === message.images.length - 1 &&
          index % 2 === 0
      }"
      @click="showImage(index)"
    >
      <MediaImg
        :url="image.thumbnailUrl"
        kind="image"
        no-callout
        img-class="border-0 object-cover transition"
        :img-style="calculateSize(index, image)"
      />
      <template
        v-if="
          image.thumbnailUrl?.startsWith('data') &&
          message.status !== MessageStatus.Failed
        "
      >
        <div class="absolute inset-0 bg-black/50" />
        <!--
          ROUND 14: replaces RadialProgress's hardcoded `#2F495E` track and
          the arc's off-palette `#60a5fa`. See FileMessageContent.vue for
          the full diagnosis.

          This ring is coloured DIFFERENTLY from the file-bubble one, and
          deliberately so: it sits on the scrim above, which is a fixed dark
          wash over a photo, not a themed surface. A theme-following token
          on a theme-invariant ground flips out from under itself — in
          neutral-light `accent-vivid` is a mid grey (#616161) that would
          sit on a darkened photo at roughly 2:1, under the 3:1 a graphic
          needs. So the ring takes the same fixed white the `%` label here
          already (correctly) uses: white is unchanged by colour mode and needs
          no token, and it holds against any photo the scrim darkens. The
          track is that same white at low alpha, so it reads as the arc's
          unfilled remainder rather than as a second colour.

          `diameter` 48 -> 56 matches the file bubble so `100%` stops
          crowding the ring; thumbnails are >=200px in every branch of
          calculateImageSize, so there is room.
        -->
        <RadialProgress
          class="absolute!"
          :diameter="56"
          :completed-steps="
            uploadProgresses[`${image.id}-thumbnail`] !== undefined
              ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                  (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                  2) *
                100
              : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
          "
          :total-steps="100"
          :start-color="'white'"
          :stop-color="'white'"
          :stroke-width="4"
          :inner-stroke-width="4"
          :inner-stroke-color="'rgb(255 255 255 / 0.35)'"
        >
          <span class="text-xs font-medium text-white">
            {{
              Math.round(
                uploadProgresses[`${image.id}-thumbnail`] !== undefined
                  ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                      (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                      2) *
                      100
                  : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
              )
            }}%
          </span>
        </RadialProgress>
      </template>
    </div>
  </div>

  <ContentLightboxDialog
    :open="lightboxOpen"
    :image="selectedImage"
    :media-items="previewMediaItems"
    :media-index="lightboxIndex"
    :selected-media="selectedMedia"
    :media-count="mediaCount"
    :can-navigate-previous="canNavigatePrevious"
    :can-navigate-next="canNavigateNext"
    :previous-media="previousMedia"
    :next-media="nextMedia"
    :room-id="message.roomId"
    @update:open="lightboxOpen = $event"
    @update:media-index="lightboxIndex = $event"
    @close="closeLightbox"
  />
</template>

