<script setup lang="ts">
import {
  MoreHorizontal,
  Reply,
  RotateCcw,
  Smile,
  Users,
  X
} from 'lucide-vue-next'
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { MessageStatus } from '../classes/message'
import { bumpActionsHandoffGuard } from '../composables/useActionsHandoffGuard'
import {
  flattenMenuGroups,
  useMessageActionItems,
  type ActionItem,
  type ActionType
} from '../composables/useMessageActionItems'
import { PORTAL_HOST_SELECTOR } from '../runtime/portalHost'
import MenuItemContent from './MenuItemContent.vue'
import MessageEmojiPicker from './MessageEmojiPicker.vue'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuPortal,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

const props = defineProps<{
  messageId: string
  direction: 'outgoing' | 'incoming'
  canCopy: boolean
  canReply: boolean
  canTranslate: boolean
  canEdit: boolean
  isSuperuser: boolean
  isGroupRoom: boolean
  status: MessageStatus
  compactMode?: boolean
  hasReactions?: boolean
}>()

const actionGroups = useMessageActionItems({
  canReply: () => props.canReply,
  canCopy: () => props.canCopy,
  canEdit: () => props.canEdit,
  isOutgoing: () => props.direction === 'outgoing',
  isSuperuser: () => props.isSuperuser,
  isGroupRoom: () => props.isGroupRoom
})

// The emoji-react entry is not part of `useMessageActionItems` (it opens the
// emoji picker rather than emitting an ActionType), but it still needs to
// participate in separator placement, so it's folded in as its own
// always-non-empty group ahead of the permission-driven ones.
type ReactMenuItem = { type: 'react'; icon: typeof Smile; labelKey: string }
type MenuItem = ActionItem | ReactMenuItem

// `viewReactions` joins the react entry in this same first group rather than
// getting one of its own: both are about reactions, and a separator between
// them would read as two unrelated sections. It is gated on the message
// actually having reactions — the sheet it opens would otherwise be empty.
const menuEntries = computed(() =>
  flattenMenuGroups<MenuItem>([
    {
      items: [
        { type: 'react' as const, icon: Smile, labelKey: 'emoji' },
        ...(props.hasReactions
          ? [
              {
                type: 'viewReactions' as const,
                icon: Users,
                labelKey: 'viewReactions'
              }
            ]
          : [])
      ]
    },
    ...actionGroups.value
  ])
)

const emit = defineEmits<{
  reply: []
  edit: []
  copy: []
  translate: []
  delete: []
  unsend: []
  retry: []
  deleteFailedMessage: []
  selectEmoji: [emoji: string]
  viewReactions: []
  'update:dropdownOpen': [value: boolean]
  dismiss: []
  open: []
  close: []
}>()

// 分開追蹤 more menu 和 emoji picker 的狀態
// Every DropdownMenu below is `:modal="false"`. Radix's modal mode disables
// pointer events on everything outside the open menu (to detect
// "click outside"), which swallows the very click meant to switch to a
// different trigger — the other button becomes unclickable until a second
// click. Non-modal still closes on outside pointerdown, just without
// blocking pointer events, so the same click that dismisses one menu still
// reaches (and opens) the next trigger.
const isMoreMenuOpen = ref(false)
const isEmojiPickerOpen = ref(false)

const onSelectEmoji = (emoji: string) => {
  emit('selectEmoji', emoji)
  isEmojiPickerOpen.value = false
}

// 當任一個 dropdown 開啟時，通知父元件（用於控制 mouseleave 行為）
const isDropdownOpen = defineModel<boolean>('dropdownOpen', { default: false })

watch(
  [isMoreMenuOpen, isEmojiPickerOpen],
  ([more, emoji], [prevMore, prevEmoji]) => {
    const open = more || emoji
    const prevOpen = prevMore || prevEmoji
    isDropdownOpen.value = open
    if (open && !prevOpen) {
      emit('open')
    } else if (!open && prevOpen) {
      emit('close')
    }
  }
)

// ChatRoom.vue tracks open-popover ownership in a Set keyed by message id,
// and locks hover-claiming for the WHOLE list while that set is non-empty.
// The set only shrinks on a `close` emit. If this toolbar unmounts with its
// menu still open — the virtualiser recycles the row, the room switches,
// the message list tears down — no `close` event fires through the normal
// v-model path, the id is stranded, and every row in the list becomes
// permanently unhoverable until a remount. Emitting here on unmount is the
// release path for exactly that case. Gated on `isMoreMenuOpen ||
// isEmojiPickerOpen` so a toolbar that unmounts with nothing open (the
// common case, e.g. during scroll) doesn't fire spuriously.
onBeforeUnmount(() => {
  if (isMoreMenuOpen.value || isEmojiPickerOpen.value) {
    // Setting the `dropdownOpen` model ref emits `update:dropdownOpen`
    // itself (defineModel wires that up) — no separate emit needed for it.
    isDropdownOpen.value = false
    emit('close')
  }
})

const handleAction = (action: ActionType) => {
  ;(emit as (event: ActionType) => void)(action)
}

const openEmojiPickerFromMenu = () => {
  // Both flip in the same synchronous tick (not nextTick): letting the more
  // menu unmount a frame before the emoji picker mounts leaves the cursor
  // briefly hovering whatever message bubble was underneath the floating
  // more-menu (it's portalled, so it can sit well above this row). See
  // useActionsHandoffGuard.ts for why that reveal needs guarding.
  bumpActionsHandoffGuard()
  isEmojiPickerOpen.value = true
  isMoreMenuOpen.value = false
}

// The react entry is always present, so `menuEntries` is never empty — kept
// as a named computed anyway so the menu-gating `v-if`s below read as
// intentional rather than a stray `true`.
const hasMenuEntries = computed(() => menuEntries.value.length > 0)
</script>

<template>
  <!-- Compact Mode (Mobile) -->
  <div v-if="compactMode" class="flex items-center justify-center gap-4">
    <MessageEmojiPicker
      v-if="!isMoreMenuOpen"
      v-model:open="isEmojiPickerOpen"
      @select="
        (emoji) => {
          emit('selectEmoji', emoji)
          emit('dismiss')
        }
      "
    />

    <DropdownMenu
      v-if="hasMenuEntries"
      v-model:open="isMoreMenuOpen"
      :modal="false"
      @update:open="(open) => !open && emit('dismiss')"
    >
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          data-testid="message-menu-trigger"
          :data-message-id="messageId"
          class="flex items-center justify-center rounded-full bg-white/20 p-2"
        >
          <MoreHorizontal class="h-5 w-5 cursor-pointer text-white" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuPortal :to="PORTAL_HOST_SELECTOR">
        <DropdownMenuContent
          data-testid="message-action-menu"
          align="center"
          side="top"
          :side-offset="8"
        >
          <template v-for="(entry, index) in menuEntries" :key="index">
            <DropdownMenuSeparator v-if="entry.kind === 'separator'" />
            <DropdownMenuItem
              v-else-if="entry.item.type === 'react'"
              data-testid="menu-item-react"
              @select="openEmojiPickerFromMenu"
            >
              <Smile class="mr-2 h-3.5 w-3.5 text-content-muted" />
              <span>{{ $t('emoji') }}</span>
            </DropdownMenuItem>
            <DropdownMenuItem
              v-else
              :data-testid="`menu-item-${entry.item.type}`"
              :class="
                entry.item.danger && 'text-danger-vivid focus:text-danger-vivid'
              "
              @select="handleAction(entry.item.type as ActionType)"
            >
              <MenuItemContent
                :icon="entry.item.icon"
                :label="$t(entry.item.labelKey)"
                :danger="entry.item.danger"
              />
            </DropdownMenuItem>
          </template>
        </DropdownMenuContent>
      </DropdownMenuPortal>
    </DropdownMenu>
  </div>

  <!-- Outgoing Actions -->
  <!--
    Round action buttons use `hover:bg-surface-hover`, not `accent-subtle`.
    `accent-subtle` can be chromatic, so on a neutral `bg-surface`
    resting fill that hover was a hue shift, not a lightness change — the same
    class of mistake flagged twice on this branch already. `surface-muted` is
    the token every other bg-surface hover in this codebase already uses
    (RoomList.vue, RoomCell.vue, ChatRoomInfo.vue, TextFormatMenu.vue,
    AddToFolderModal.vue) and it moves lightness only. Measured resting/hover
    ΔE76: blue-light 5.77, blue-dark 6.74, neutral-light 4.51 (short of the
    >=5 perceptibility floor documented in style.css, but the same shortfall
    every other surface-muted hover in the app already carries in this
    preset), neutral-dark 6.94. Icon (text-content-subtle) contrast against
    the hover fill stays >=4.5:1 in all four.

    Icon glyphs inside these 30px (`h-7.5 w-7.5`) circles were shrunk from
    `h-5 w-5`/`h-5.5 w-5.5` (20px/22px) to `h-4 w-4` (16px) — the button
    diameter and hit target are untouched, only the glyph inside got
    smaller, via padding (the icon no longer fills the circle edge to edge).
    16px also matches the `RotateCcw` retry icon already living in this same
    button row, so the toolbar now reads as one consistent icon scale rather
    than two. Contrast is unaffected by size: `text-content-subtle` against
    `bg-surface`/`bg-surface-muted` is a per-pixel colour comparison, not a
    function of glyph area, and it clears the 3:1 non-text floor by a wide
    margin across the audited palette and colour-mode combinations (i.e. even
    the worst case still clears the TEXT floor, not just the icon one).
  -->
  <div
    v-else-if="direction === 'outgoing'"
    data-testid="message-actions-toolbar"
    class="flex w-fit items-center justify-end gap-2 justify-self-end"
  >
    <template v-if="status === MessageStatus.Delivered">
      <!-- More dropdown -->
      <DropdownMenu
        v-if="hasMenuEntries"
        v-model:open="isMoreMenuOpen"
        :modal="false"
      >
        <DropdownMenuTrigger as-child>
          <button
            type="button"
            data-testid="message-menu-trigger"
            :data-message-id="messageId"
            class="tooltip-trigger flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
          >
            <MoreHorizontal
              class="h-4 w-4 cursor-pointer text-content-subtle"
            />
            <span v-if="!isMoreMenuOpen" class="tooltip">{{ $t('more') }}</span>
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuPortal :to="PORTAL_HOST_SELECTOR">
          <DropdownMenuContent
            data-testid="message-action-menu"
            align="end"
            side="top"
            :side-offset="8"
          >
            <template v-for="(entry, index) in menuEntries" :key="index">
              <DropdownMenuSeparator v-if="entry.kind === 'separator'" />
              <DropdownMenuItem
                v-else-if="entry.item.type === 'react'"
                data-testid="menu-item-react"
                @select="openEmojiPickerFromMenu"
              >
                <Smile class="mr-2 h-3.5 w-3.5 text-content-muted" />
                <span>{{ $t('emoji') }}</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                v-else
                :data-testid="`menu-item-${entry.item.type}`"
                :class="
                  entry.item.danger &&
                  'text-danger-vivid focus:text-danger-vivid'
                "
                @select="handleAction(entry.item.type as ActionType)"
              >
                <MenuItemContent
                  :icon="entry.item.icon"
                  :label="$t(entry.item.labelKey)"
                  :danger="entry.item.danger"
                />
              </DropdownMenuItem>
            </template>
          </DropdownMenuContent>
        </DropdownMenuPortal>
      </DropdownMenu>

      <button
        v-if="canReply"
        type="button"
        data-testid="message-reply-button"
        :data-message-id="messageId"
        class="tooltip-trigger flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
        @click="emit('reply')"
      >
        <Reply class="h-4 w-4 cursor-pointer text-content-subtle" />
        <span class="tooltip">{{ $t('reply') }}</span>
      </button>

      <MessageEmojiPicker
        v-model:open="isEmojiPickerOpen"
        @select="onSelectEmoji"
      />
    </template>

    <template v-else-if="status === MessageStatus.Failed">
      <button
        type="button"
        class="flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
        @click="emit('deleteFailedMessage')"
      >
        <X class="h-4 w-4 cursor-pointer text-content-subtle" />
      </button>
      <button
        type="button"
        class="flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
        @click="emit('retry')"
      >
        <RotateCcw class="h-4 w-4 cursor-pointer text-content-subtle" />
      </button>
    </template>
  </div>

  <!-- Incoming Actions -->
  <div
    v-else
    data-testid="message-actions-toolbar"
    class="flex w-fit shrink-0 items-center justify-start gap-2 justify-self-start"
  >
    <MessageEmojiPicker
      v-model:open="isEmojiPickerOpen"
      @select="onSelectEmoji"
    />

    <button
      v-if="canReply"
      type="button"
      data-testid="message-reply-button"
      :data-message-id="messageId"
      class="tooltip-trigger flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
      @click="emit('reply')"
    >
      <Reply class="h-4 w-4 cursor-pointer text-content-subtle" />
      <span class="tooltip">{{ $t('reply') }}</span>
    </button>

    <!-- More dropdown -->
    <DropdownMenu
      v-if="hasMenuEntries"
      v-model:open="isMoreMenuOpen"
      :modal="false"
    >
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          data-testid="message-menu-trigger"
          :data-message-id="messageId"
          class="tooltip-trigger flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
        >
          <MoreHorizontal class="h-4 w-4 cursor-pointer text-content-subtle" />
          <span v-if="!isMoreMenuOpen" class="tooltip">{{ $t('more') }}</span>
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuPortal :to="PORTAL_HOST_SELECTOR">
        <DropdownMenuContent
          data-testid="message-action-menu"
          align="start"
          side="top"
          :side-offset="8"
        >
          <template v-for="(entry, index) in menuEntries" :key="index">
            <DropdownMenuSeparator v-if="entry.kind === 'separator'" />
            <DropdownMenuItem
              v-else-if="entry.item.type === 'react'"
              data-testid="menu-item-react"
              @select="openEmojiPickerFromMenu"
            >
              <Smile class="mr-2 h-3.5 w-3.5 text-content-muted" />
              <span>{{ $t('emoji') }}</span>
            </DropdownMenuItem>
            <DropdownMenuItem
              v-else
              :data-testid="`menu-item-${entry.item.type}`"
              :class="
                entry.item.danger && 'text-danger-vivid focus:text-danger-vivid'
              "
              @select="handleAction(entry.item.type as ActionType)"
            >
              <MenuItemContent
                :icon="entry.item.icon"
                :label="$t(entry.item.labelKey)"
                :danger="entry.item.danger"
              />
            </DropdownMenuItem>
          </template>
        </DropdownMenuContent>
      </DropdownMenuPortal>
    </DropdownMenu>
  </div>
</template>
