/**
 * Shared portal host for the SDK's floating UI (modals, dropdown menus,
 * bottom sheets/overlays).
 *
 * These layers portal/teleport to `<body>` deliberately, to escape ancestor
 * `overflow` clipping and stacking contexts — do NOT "fix" this by
 * re-parenting them into the SDK root; that would reintroduce clipping bugs.
 * But a plain `to="body"` also means they render OUTSIDE the SDK root, so
 * they never inherit the SDK root's `.dark` mode or its inline design-token
 * values unless those values are mirrored onto a body-level element.
 *
 * This module gives the SDK ONE element it owns in `<body>`, keeps that
 * element's `dark` class and design tokens in sync with whichever SDK root is
 * currently mounted, and every portal/teleport in the SDK targets that element
 * (`PORTAL_HOST_SELECTOR`) instead of `"body"`.
 *
 * This also supports a consumer who applies `.dark` to their OWN wrapper
 * (rather than relying on
 * `vue-dark-switch` putting it on `<html>`, as this repo's demo does) would
 * previously get modals/menus stuck in light mode, because those layers
 * never inherited `.dark` from anywhere. Mirroring the class explicitly onto
 * an owned host fixes that too.
 */

import { DESIGN_TOKEN_NAMES } from './theme'

const PORTAL_HOST_ID = 'imkit-portal-host'
const MODE_CLASSES = ['dark']
const DESIGN_TOKEN_PROPERTIES = DESIGN_TOKEN_NAMES.map(
  (name) => `--color-${name}`
)

/** CSS selector every SDK portal/teleport should target instead of "body". */
export const PORTAL_HOST_SELECTOR = `#${PORTAL_HOST_ID}`

let hostEl: HTMLDivElement | null = null

type PaletteSourceRegistration = {
  source: Element
  observer: MutationObserver
}

const registrations: PaletteSourceRegistration[] = []

const activeRegistration = (): PaletteSourceRegistration | undefined =>
  registrations.at(-1)

function ensureHost(): HTMLDivElement {
  if (hostEl?.isConnected) return hostEl
  const existing = document.getElementById(
    PORTAL_HOST_ID
  ) as HTMLDivElement | null
  hostEl = existing ?? document.createElement('div')
  hostEl.id = PORTAL_HOST_ID
  if (!hostEl.isConnected) document.body.appendChild(hostEl)
  return hostEl
}

// Create the host eagerly at module-evaluation time (not just from
// `registerPortalPaletteSource`): a `<Teleport>`/`<...Portal>` requires its
// target to already exist in the DOM when IT mounts, and that can happen
// before any SDK root has had a chance to call `registerPortalPaletteSource`
// (e.g. a consumer mounting `ModalsContainer` standalone, or a modal that
// opens during the SDK root's own first render). Themeless is fine as a
// starting state — `registerPortalPaletteSource` corrects the mode and tokens as soon
// as a root mounts.
if (typeof document !== 'undefined') {
  ensureHost()
}

function syncPalette(source: Element, host: HTMLElement): void {
  for (const cls of MODE_CLASSES) {
    host.classList.toggle(cls, source.classList.contains(cls))
  }
  const sourceStyle = (source as HTMLElement).style
  for (const property of DESIGN_TOKEN_PROPERTIES) {
    const value = sourceStyle?.getPropertyValue(property).trim() ?? ''
    if (value) host.style.setProperty(property, value)
    else host.style.removeProperty(property)
  }
}

/**
 * Registers `sourceEl` (an SDK mount root — e.g. MainView's root `<div>`, or
 * the custom element's wrapper `<div>`) as the colour-mode and design-token
 * source for the shared portal host. It copies `.dark` and the derived CSS
 * custom properties immediately, then keeps both in sync at runtime.
 *
 * Call once per SDK mount, from that mount's root element, on mount/connect.
 * The latest registration is active. Call the returned cleanup function on
 * unmount/disconnect; removing the active source restores the previous one.
 * The host is removed only after every registered mount has cleaned up.
 */
export function registerPortalPaletteSource(sourceEl: Element): () => void {
  const host = ensureHost()
  syncPalette(sourceEl, host)

  const registration: PaletteSourceRegistration = {
    source: sourceEl,
    observer: new MutationObserver(() => {
      if (activeRegistration() === registration) {
        syncPalette(sourceEl, host)
      }
    })
  }
  registrations.push(registration)
  const { observer } = registration
  observer.observe(sourceEl, {
    attributes: true,
    attributeFilter: ['class', 'style']
  })

  let cleaned = false
  return () => {
    if (cleaned) return
    cleaned = true
    observer.disconnect()
    const index = registrations.indexOf(registration)
    const wasActive = index === registrations.length - 1
    if (index !== -1) registrations.splice(index, 1)
    if (registrations.length === 0) {
      hostEl?.remove()
      hostEl = null
    } else if (wasActive) {
      syncPalette(activeRegistration()!.source, host)
    }
  }
}
