import type ChatRoomContent from '../../classes/chatRoomContent'
import Folder from '../../classes/folder'
import LinkPreview from '../../classes/linkPreview'
import Message from '../../classes/message'
import MessageMultiList from '../../classes/messageMultiList'
import Room from '../../classes/room'
import User from '../../classes/user'
import { SearchType } from '../../enums/searchType'

export type TypingStatus =
  | { kind: 'expires'; timeoutId: number }
  | { kind: 'until-message'; messageId: string; timeoutId: number }

export type ImkitState = {
  isRequesting: { [api: string]: Date | null }
  users: { [uid: string]: User }
  rooms: { [id: string]: Room }
  sortedRooms: Room[]
  numberOfFetchedRooms: number
  numberOfTotalRooms: number
  uploadProgresses: { [id: string]: number }
  downloadProgresses: { [id: string]: number }
  linkPreviews: { [url: string]: LinkPreview }
  loadingLinkPreviews: Set<string>
  actionMenuRoomId: string
  folders: { [id: string]: Folder }
  sortedFolderIds: string[]
  roomIdsInFolders: { [roomId: string]: boolean }
  messageDrafts: Record<string, string>
  messageDraftsLoaded: boolean
  messageDraftPrefExists: Record<string, boolean>
  messageDraftRevision: number
  messageDraftRoomRevisions: Record<string, number>
  selectedRoomIdsForCreateFolder: { [roomId: string]: Date }
  selectedFolderId: string
  searchKeyword: string
  searchType: SearchType
  searchRooms: { [type: string]: Room[] | Folder[] }
  roomTag: string
  sortBy: string
  sortUnreadFirst: number
  stickyUnreadRoomIds: { [id: string]: true }
  deliveringMessages: Map<string, Message>
  processingMessages: Map<string, Message>
  selectedRoomId: string
  messageMultiLists: Map<string, MessageMultiList>
  numberOfTotalMessages: Map<string, number>
  replyId: string
  editingMessageId: string
  navigationRevision: number
  navigationTargetId: string
  isRoomInfoVisible: boolean
  isRoomContentVisible: boolean
  isTyping: { [uid: string]: TypingStatus }
  isSearchInRoomMode: boolean
  messageSearchKeyword: string
  searchedMessageIds: Map<string, string[]>
  blockedUsers: { [uid: string]: boolean }
  activeActionMessageId: string
  isNavigatingToMessage: boolean
  sessionEpoch: number
  reconnectResyncTick: number
  lastReconnectResyncAt: number
  trailingReconnectResyncTimer: ReturnType<typeof setTimeout> | null
  aggregateCoalesceTimer: ReturnType<typeof setTimeout> | null
  chatRoomContentPreview: ChatRoomContent[]
  chatRoomContentPreviewRoomId: string
  chatRoomContentPreviewLoading: boolean
  chatRoomContentPreviewOffset: number
  chatRoomContentPreviewTotalCount: number
  chatRoomContentPreviewHasMore: boolean
  chatRoomContentPreviewLoadingMore: boolean
  chatRoomContentMedia: ChatRoomContent[]
  chatRoomContentFiles: ChatRoomContent[]
  chatRoomContentMediaRoomId: string
  chatRoomContentFilesRoomId: string
  chatRoomContentMediaLoading: boolean
  chatRoomContentFilesLoading: boolean
  chatRoomContentMediaOffset: number
  chatRoomContentMediaTotalCount: number
  chatRoomContentMediaHasMore: boolean
  chatRoomContentMediaLoadingMore: boolean
  chatRoomContentFilesOffset: number
  chatRoomContentFilesTotalCount: number
  chatRoomContentFilesHasMore: boolean
  chatRoomContentFilesLoadingMore: boolean
}

export const createState = (): ImkitState => ({
  isRequesting: {},
  users: {},
  rooms: {},
  sortedRooms: [],
  numberOfFetchedRooms: 0,
  numberOfTotalRooms: 0,
  uploadProgresses: {},
  downloadProgresses: {},
  linkPreviews: {},
  loadingLinkPreviews: new Set<string>(),
  actionMenuRoomId: '',
  folders: {},
  sortedFolderIds: [],
  roomIdsInFolders: {},
  messageDrafts: {},
  messageDraftsLoaded: false,
  messageDraftPrefExists: {},
  messageDraftRevision: 0,
  messageDraftRoomRevisions: {},
  selectedRoomIdsForCreateFolder: {},
  selectedFolderId: '',
  searchKeyword: '',
  searchType: SearchType.RoomName,
  searchRooms: {},
  roomTag: '',
  sortBy: '-lastMessage',
  sortUnreadFirst: 0,
  stickyUnreadRoomIds: {},
  deliveringMessages: new Map(),
  processingMessages: new Map(),
  selectedRoomId: '',
  messageMultiLists: new Map(),
  numberOfTotalMessages: new Map(),
  replyId: '',
  editingMessageId: '',
  navigationRevision: 0,
  navigationTargetId: '',
  isRoomInfoVisible: false,
  isRoomContentVisible: false,
  isTyping: {},
  isSearchInRoomMode: false,
  messageSearchKeyword: '',
  searchedMessageIds: new Map(),
  blockedUsers: {},
  activeActionMessageId: '',
  isNavigatingToMessage: false,
  // Identifies the authenticated store session. Async actions capture this
  // value so a response started before resetSession cannot write into the
  // next account when both accounts happen to use the same room id.
  sessionEpoch: 0,
  // Bumped on every socket reconnect; the open room's message-list composable
  // watches this to reload and backfill messages missed while disconnected.
  reconnectResyncTick: 0,
  // Timestamp of the last reconnect resync; coalesces a burst (the >60s
  // visibility return fires it directly AND the socket 'connect' follow-up
  // fires it again) into a single refresh within a short cooldown window.
  lastReconnectResyncAt: 0,
  // A resync suppressed by the cooldown is deferred (not dropped) to the end
  // of the window via this timer — the follow-up is the only call that can see
  // messages committed after the first resync's snapshot.
  trailingReconnectResyncTimer: null,
  // Trailing-throttle handle that coalesces a burst of socket-driven re-sorts
  // into a single aggregateRoomsAndFolders() — see scheduleAggregateRoomsAndFolders.
  aggregateCoalesceTimer: null,
  chatRoomContentPreview: [],
  chatRoomContentPreviewRoomId: '',
  chatRoomContentPreviewLoading: false,
  chatRoomContentPreviewOffset: 0,
  chatRoomContentPreviewTotalCount: 0,
  chatRoomContentPreviewHasMore: true,
  chatRoomContentPreviewLoadingMore: false,
  chatRoomContentMedia: [],
  chatRoomContentFiles: [],
  chatRoomContentMediaRoomId: '',
  chatRoomContentFilesRoomId: '',
  chatRoomContentMediaLoading: false,
  chatRoomContentFilesLoading: false,
  chatRoomContentMediaOffset: 0,
  chatRoomContentMediaTotalCount: 0,
  chatRoomContentMediaHasMore: true,
  chatRoomContentMediaLoadingMore: false,
  chatRoomContentFilesOffset: 0,
  chatRoomContentFilesTotalCount: 0,
  chatRoomContentFilesHasMore: true,
  chatRoomContentFilesLoadingMore: false
})
