import i18n from '../i18n'
import { getUid } from '../runtime/uid'
import { getImkitStore } from '../stores/imkit'
import Message from './message'
import User from './user'

export enum RoomType {
  Direct = 'direct',
  Group = 'group'
}

type Avatar = {
  url: string
  name: string
}

// Shapes describing the untrusted room payload as it arrives from the API /
// socket boundary. Known fields are typed but optional because any of them may
// be absent in a raw payload; the index signature keeps the type assignable
// from the `Record<string, unknown>` payloads the call sites pass. The runtime
// guards in the constructor — not these types — are what make construction
// robust against missing arrays (M25/M71).
export interface RawRoomMember {
  _id: string
  clientType?: string
  members?: { _id: string }[]
}

export interface RawRoom {
  [key: string]: unknown
  members?: RawRoomMember[]
}

type RoomPref = {
  tags: string[]
  tagColors: { [tag: string]: string }
  sticky: boolean
  hidden: boolean
} | null

// The constructor's concrete view of the consumed scalar fields. `RawRoom`
// itself stays permissive (index signature) so the API/socket call sites can
// pass their `Record<string, unknown>` / `any` payloads; the constructor casts
// to this read shape internally so the field assignments stay type-checked
// without changing the trusting runtime behavior the payload always had.
interface RawRoomFields {
  _id: string
  name: string
  roomType: string
  createdTimeMS: number
  cover: string
  unread: number
  memberProperties: { client: string; lastRead: string }[]
  extParams: string
  pref: RoomPref
  roomTags: string[]
  muted: boolean
  isSuperuser: boolean
  isMentioned: boolean
}

const safeGetUsers = (): Record<string, User> => {
  try {
    return getImkitStore().users
  } catch {
    return {}
  }
}

class Room {
  id: string
  name: string
  type: RoomType
  createdAt: number
  updatedAt: number
  memberIds: string[]
  isOutgoingGroupSender: { [id: string]: boolean }
  coverUrl: string
  lastMessage: Message | null
  numberOfUnread: number
  lastReadMessageId: { [uid: string]: string }
  pref: RoomPref
  roomTags: string[]
  extra: Record<string, unknown>
  muted: boolean = false
  isSuperuser: boolean = false
  isMentioned: boolean = false

  constructor(raw: RawRoom, uid: string) {
    const { members, lastMessage } = raw
    const {
      _id: id,
      name,
      roomType: type,
      createdTimeMS: createdAt,
      cover: coverUrl,
      unread,
      memberProperties,
      extParams,
      pref,
      roomTags,
      muted,
      isSuperuser,
      isMentioned
    } = raw as unknown as RawRoomFields
    this.id = id
    this.name = name
    // `roomType` is an untrusted string from the payload; it is trusted to be a
    // RoomType here, while the `type === 'custom'` branch below re-resolves the
    // out-of-enum 'custom' sentinel from parsed extParams.
    this.type = (type as RoomType) || RoomType.Direct
    this.createdAt = createdAt
    this.lastMessage = Message.createReactive(lastMessage)
    this.updatedAt = this.lastMessage?.createdAt ?? createdAt
    this.memberIds = []
    this.isOutgoingGroupSender = {}
    const safeMembers: RawRoomMember[] = Array.isArray(members) ? members : []
    for (const member of safeMembers) {
      if (member.clientType === 'user' && member._id) {
        this.memberIds.push(member._id)
      }

      if (
        member.clientType === 'group' &&
        Array.isArray(member.members) &&
        member.members.some((m) => m._id === uid)
      ) {
        for (const nested of member.members) {
          this.isOutgoingGroupSender[nested._id] = true
        }
      }
    }
    this.coverUrl = coverUrl ?? ''
    this.numberOfUnread = unread ?? 0
    this.lastReadMessageId = {}
    this.pref = pref
    this.roomTags = roomTags ?? []
    this.muted = muted ?? false
    if (memberProperties) {
      for (const { client, lastRead } of memberProperties) {
        if (lastRead) {
          this.lastReadMessageId[client] = lastRead
        }
      }
    }
    try {
      this.extra = JSON.parse(extParams)
    } catch {
      this.extra = {}
    }
    if (type === 'custom') {
      // extra.roomType is untrusted JSON; casting it straight to RoomType would
      // let a non-member value (e.g. 'broadcast') or undefined sit in a field
      // typed RoomType, silently breaking every `type === RoomType.*` check.
      // Only 'group' resolves to Group; anything else collapses to Direct.
      this.type =
        this.extra.roomType === RoomType.Group
          ? RoomType.Group
          : RoomType.Direct
    }
    this.isSuperuser = isSuperuser ?? false
    this.isMentioned = isMentioned ?? false
  }

  get isGroup(): boolean {
    return this.type === RoomType.Group
  }

  get memberIdsWithoutMeAndMyGroup(): string[] {
    const users = safeGetUsers()
    const uid = getUid()
    return this.memberIds.filter(
      (id: string) => id !== uid && !users[id]?.memberIds?.[uid]
    )
  }

  get displayName(): string {
    const users = safeGetUsers()
    const uid = getUid()
    if (this.name) {
      return this.name
    } else if (this.memberIdsWithoutMeAndMyGroup.length === 0) {
      // Plain class getter read during render (no setup context), so use the
      // global i18n instance — useI18n() would throw here. Matches message.ts.
      return i18n.global.t('emptyChat')
    } else if (this.type == RoomType.Direct) {
      // The peer may not be loaded yet (or the store is unavailable), so the
      // lookup can be undefined; coerce to '' to honor the `: string` return.
      return (
        this.memberIdsWithoutMeAndMyGroup.map((id: string) => users[id])[0]
          ?.nickname ?? ''
      )
    } else if (this.isGroup) {
      return this.memberIds
        .filter((id: string) => id !== uid)
        .map((id: string) => users[id]?.nickname ?? '')
        .filter((nickname: string) => nickname.length > 0)
        .join(', ')
    }
    return ''
  }
  get avatars(): Avatar[] {
    const users = safeGetUsers()
    const uid = getUid()
    if (this.coverUrl && this.coverUrl.length > 0) {
      return [{ url: this.coverUrl, name: this.displayName ?? '' }]
    } else if (this.memberIdsWithoutMeAndMyGroup.length === 0) {
      return [
        {
          url: users[uid]?.avatarUrl ?? '',
          name: users[uid]?.nickname ?? ''
        }
      ]
    } else if (this.type == RoomType.Direct) {
      return this.memberIdsWithoutMeAndMyGroup.map((id: string) => ({
        url: users[id]?.avatarUrl ?? '',
        name: users[id]?.nickname ?? ''
      }))
    } else if (this.isGroup) {
      return this.memberIds
        .map((id: string) => users[id])
        .filter((user): user is User => !!user)
        .sort((a, b) => {
          if (a.id === uid) return 1
          if (b.id === uid) return -1
          return (b.avatarUrl ?? '').length - (a.avatarUrl ?? '').length
        })
        .map((user: User) => ({
          url: user.avatarUrl ?? '',
          name: user.nickname ?? ''
        }))
    }
    return [{ url: '', name: this.displayName ?? '' }]
  }
}
export default Room
