<script setup lang="ts">
import { ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)

const cancel = () => vfm.closeAll()
const props = defineProps<{ roomId: string }>()

// Only the hide direction confirms — unhiding is the recovery path for a
// mistaken hide, and putting a dialog in front of recovery makes the mistake
// harder to undo than to make. This modal is only ever opened from
// RoomCell's `toggleHidden` when the room is not already hidden; unhiding
// calls `imkit.updateRoomPrefs` directly, with no modal in between.
const hideRoom = async () => {
  isLoading.value = true
  try {
    await imkit.updateRoomPrefs({
      roomId: props.roomId,
      prefs: {
        hidden: true
      }
    })
    vfm.closeAll()
  } catch (error) {
    console.error('Error hiding room:', error)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('hideRoomConfirmationTitle')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('hide')"
    confirm-test-id="hide-room-confirm-action"
    :loading="isLoading"
    @cancel="cancel"
    @confirm="hideRoom"
  >
    {{ $t('hideRoomConfirmationMessage') }}
  </ConfirmDialogShell>
</template>
