<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
const text = computed(() => props.message.template.text ?? '')
const actions = computed(() =>
  Array.isArray(props.message.template.actions)
    ? props.message.template.actions.slice(0, 2)
    : []
)
</script>

<template>
  <!-- Self-contained plate, direction-tinted from the bubble pair — same
       reasoning as TemplateMessageButtonsContent.vue, which see. This
       component also had no background of its own and relied on the
       MessageCell wrapper that is now transparent, and its outgoing
       `text-slate-100` was likewise a raw near-white invisible on the old
       light plate. -->
  <div
    class="w-[250px] overflow-hidden rounded-lg text-base"
    :class="
      isIncoming
        ? 'bg-message text-content'
        : 'bg-message-own text-message-own-content'
    "
  >
    <div data-testid="template-message-body" class="px-4 py-2.5">
      {{ text.substring(0, 240) }}
    </div>
    <div
      class="flex divide-x border-t"
      :class="
        isIncoming
          ? 'divide-content/8 border-content/8'
          : 'divide-message-own-content/14 border-message-own-content/14'
      "
    >
      <div
        v-for="action in actions"
        :key="action.label"
        class="flex grow cursor-pointer items-center justify-center p-2"
        :class="isIncoming ? 'text-content-muted' : 'text-message-own-content'"
        @click="actionHandler(message.roomId, action)"
      >
        {{ action.label }}
      </div>
    </div>
  </div>
</template>

<style scoped></style>
