<template>
  <span v-if="!highlight" v-text="text" />
  <template v-else>
    <template v-for="(chunk, index) in chunks" :key="index">
      <span
        v-if="chunk.highlight"
        class="text-accent-vivid"
        v-text="chunk.text"
      />
      <span v-else v-text="chunk.text" />
    </template>
  </template>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { escapeRegExp } from '../utils/escapeRegExp'

const props = defineProps<{
  text: string
  highlight?: string
}>()

const chunks = computed(() => {
  if (!props.highlight) {
    return [{ text: props.text, highlight: false }]
  }
  const regex = new RegExp(`(${escapeRegExp(props.highlight)})`, 'gi')
  const parts = props.text.split(regex)
  return parts.map((part) => ({
    text: part,
    highlight: part.toLowerCase() === props.highlight?.toLowerCase()
  }))
})
</script>
