import { toRaw } from 'vue'
import type Message from '../classes/message'

type MessageEntryAnimation = {
  origin: 'local' | 'incoming'
  createdAt: number
  played: boolean
}

// Keep presentation state off Message and the API payload. Weak keys also
// release it when messages leave the store, without timers or an ID cache.
const animations = new WeakMap<Message, MessageEntryAnimation>()

export const markMessageEntryAnimation = (
  message: Message,
  origin: MessageEntryAnimation['origin'] = 'local'
) => {
  animations.set(toRaw(message), {
    origin,
    createdAt: Date.now(),
    played: false
  })
}

export const transferMessageEntryAnimation = (
  source: Message,
  target: Message
) => {
  const animation = animations.get(toRaw(source))
  if (animation) animations.set(toRaw(target), animation)
}

export const getMessageEntryAnimation = (message: Message) =>
  animations.get(toRaw(message))
