import Message from './message'

export default class MessageLinkedList {
  head: Message | null
  tail: Message | null
  length: number
  map: Map<string, Message>
  messageGroups: Map<string, Message[]>
  firstMessageOfDate: Map<number, Message>

  prev: MessageLinkedList | null = null
  next: MessageLinkedList | null = null

  // Memoised result of array(): a full head->tail walk is O(n) and was rerun on
  // every sortedMessages/realMessages recompute and pagination step. Any
  // structural mutation (append/remove/replace/absorb/resetHead/resetTail) drops
  // it so a stale snapshot can never leak a removed or pre-merge node.
  private arrayCache: Message[] | null = null

  constructor(data: Array<Record<string, unknown>>) {
    this.head = null
    this.tail = null
    this.length = 0
    this.map = new Map()
    this.messageGroups = new Map()
    this.firstMessageOfDate = new Map()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const extract = (m: any): Message[] => {
      const message = Message.createReactive(m)
      if (message) {
        return [message].concat(extract(m.reply))
      }
      return []
    }
    for (const m of data.reverse()) {
      const message = Message.createReactive(m)
      if (message) {
        this.append(message)
      }
      for (const message of extract(m.reply)) {
        // Reply targets are stored map-only (no chain linkage) so reply previews
        // resolve. But the SAME message can also be a top-level entry in this
        // page (you send a message, a newer one quotes it). append() already put
        // the linked node in map under that id; clobbering it with the detached
        // reply copy makes finds()/contains() report the linked message missing,
        // so the next merge (reconnect resync re-fetch) re-appends it as a
        // same-id duplicate. Never overwrite an existing entry.
        if (!this.map.has(message.id)) {
          this.map.set(message.id, message)
        }
      }
    }
  }

  append(message: Message) {
    if (this.contains(message.id)) return
    if (this.tail) {
      let current: Message | null = this.tail
      while (current && current.createdAt > message.createdAt) {
        current = current.prev
      }
      if (current) {
        if (current === this.tail) {
          this.tail = message
        }
        message.next = current.next
        current.next = message
        message.prev = current
      } else {
        message.next = this.head
        this.head = message
      }
      if (message.next) {
        message.next.prev = message
      }
    } else {
      this.head = this.tail = message
    }
    this.map.set(message.id, message)
    this.length++
    this.insertMessageToGroup(message)
    this.invalidateArrayCache()
  }

  insertMessageToGroup(message: Message) {
    const firstMessage = this.firstMessageOfDate.get(message.dateId)
    if (!firstMessage || firstMessage.createdAt > message.createdAt) {
      this.firstMessageOfDate.set(message.dateId, message)
    }
    if (message.isSystem) return
    // if (message.status !== MessageStatus.Delivered) return
    if (this.messageGroups.has(message.groupId)) {
      const group = this.messageGroups.get(message.groupId)
      if (group) {
        let hasInserted = false
        for (let index = group.length - 1; index >= 0; index--) {
          if (group[index].createdAt < message.createdAt) {
            if (index == group.length - 1) {
              group.push(message)
            } else {
              group.splice(index + 1, 0, message)
            }
            hasInserted = true
            break
          }
        }
        if (!hasInserted) {
          group.unshift(message)
        }
      }
    } else {
      this.messageGroups.set(message.groupId, [message])
    }
  }

  remove(id: string) {
    const target = this.finds(id)
    if (!target) return

    if (target.prev) {
      target.prev.next = target.next
    } else {
      this.head = target.next
    }

    if (target.next) {
      target.next.prev = target.prev
    } else {
      this.tail = target.prev
    }

    this.map.delete(id)
    this.length--

    const group = this.messageGroups.get(target.groupId)
    if (group) {
      const index = group.indexOf(target)
      if (index >= 0) {
        group.splice(index, 1)
        if (group.length === 0) {
          this.messageGroups.delete(target.groupId)
        }
      }
    }

    if (this.firstMessageOfDate.get(target.dateId)?.id === target.id) {
      this.recomputeFirstMessageOfDate(target.dateId)
    }
    this.invalidateArrayCache()
  }

  replace(id: string, message: Message) {
    if (id !== message.id && this.contains(message.id)) {
      // The replacement already landed via another path (socket echo or a
      // reconnect REST refill racing the POST response). Splicing would leave
      // two nodes sharing one id with the map pointing at only one; drop the
      // obsolete node instead.
      this.remove(id)
      return
    }
    const target = this.finds(id)
    if (target) {
      if (target.prev) {
        target.prev.next = message
      } else {
        this.head = message
      }
      if (target.next) {
        target.next.prev = message
      } else {
        this.tail = message
      }
      message.prev = target.prev
      message.next = target.next
      this.map.delete(id)
      this.map.set(message.id, message)
      const group = this.messageGroups.get(target.groupId)
      if (group) {
        const index = group.indexOf(target)
        if (index >= 0) {
          if (message.isSystem) {
            group.splice(index, 1)
          } else {
            group[index] = message
          }
        }
      }
      if (this.firstMessageOfDate.get(target.dateId)?.id === target.id) {
        this.firstMessageOfDate.set(target.dateId, message)
      }
      this.invalidateArrayCache()
    }
  }

  // Merge every message of another list into this one, deduped by id and kept in
  // createdAt order. append() inserts each node by createdAt and skips ids already
  // present, so ANY overlap topology — contiguous, interior, or out-of-order —
  // yields the union exactly once. This is the single lossless merge primitive
  // shared by concate(), unshift() and combine().
  //
  // The previous splice-based concate/unshift only stripped overlap that was
  // CONTIGUOUS at the joining end, so a message re-included in a page's INTERIOR
  // (e.g. a live message that sealed an interior gap during a reconnect, then
  // returned by the forward/backward refetch) was spliced in as a SECOND node
  // sharing one id — a same-id duplicate the renderer showed twice, with `length`
  // over-counted and isValid() broken. (Audit messageLinkedList.ts:209)
  private absorb(linkedList: MessageLinkedList) {
    // Fast path for a genuinely DISJOINT, already-ordered range: splice the
    // whole incoming chain in at one boundary (O(1) pointer surgery) instead of
    // re-running append()'s insertion walk per node. append() walks from the
    // tail back to the insertion point on every node, so an older-than-head page
    // costs O(n) per node — O(n*m) overall — even though the result is a plain
    // prepend. The per-node metadata bookkeeping (map/length/group/date) is
    // unavoidable and still runs once each below; only the pointer rewalk is
    // skipped. Interleaved/overlapping ranges fall through to the deduping
    // append path.
    if (!this.tryFastMerge(linkedList)) {
      let current: Message | null = linkedList.head
      while (current) {
        const next: Message | null = current.next
        current.prev = null
        current.next = null
        this.append(current)
        current = next
      }
    }
    // Reply targets live in `map` without chain linkage (see the constructor's
    // extract(m.reply)); carry them so reply previews still resolve.
    for (const [key, value] of linkedList.map) {
      if (!this.map.has(key)) {
        this.map.set(key, value)
      }
    }
  }

  // Splice an incoming chain that is wholly newer than this.tail or wholly older
  // than this.head — strictly, so the ranges are disjoint by time and cannot
  // share an id (the dedup append() does is then unnecessary). Returns false for
  // empty/empty-target lists and for any range that touches or overlaps this
  // list, leaving those to the append path. Replicates per-node bookkeeping
  // (map, length, messageGroups, firstMessageOfDate, cache) so the result is
  // identical to the append path; only the per-node pointer walk is avoided.
  private tryFastMerge(linkedList: MessageLinkedList): boolean {
    const incomingHead = linkedList.head
    const incomingTail = linkedList.tail
    if (!incomingHead || !incomingTail) return false
    if (!this.head || !this.tail) return false

    const whollyNewer = incomingHead.createdAt > this.tail.createdAt
    const whollyOlder = incomingTail.createdAt < this.head.createdAt
    if (!whollyNewer && !whollyOlder) return false

    if (whollyNewer) {
      this.tail.next = incomingHead
      incomingHead.prev = this.tail
      this.tail = incomingTail
    } else {
      this.head.prev = incomingTail
      incomingTail.next = this.head
      this.head = incomingHead
    }

    let node: Message | null = incomingHead
    while (node) {
      this.map.set(node.id, node)
      this.length++
      this.insertMessageToGroup(node)
      node = node === incomingTail ? null : node.next
    }
    this.invalidateArrayCache()
    return true
  }

  concate(linkedList: MessageLinkedList) {
    if (linkedList.length === 0) return
    this.absorb(linkedList)
  }

  unshift(linkedList: MessageLinkedList) {
    if (linkedList.length === 0) return
    this.absorb(linkedList)
  }

  // Drops a message from the group/date secondary structures. Returns true when
  // it removed the date's first-of-date entry, so the caller can repoint it to
  // the earliest surviving same-date node after the chain is re-anchored.
  private removeFromMetadata(message: Message): boolean {
    const group = this.messageGroups.get(message.groupId)
    if (group) {
      const idx = group.indexOf(message)
      if (idx >= 0) group.splice(idx, 1)
      if (group.length === 0) this.messageGroups.delete(message.groupId)
    }
    if (this.firstMessageOfDate.get(message.dateId)?.id === message.id) {
      this.firstMessageOfDate.delete(message.dateId)
      return true
    }
    return false
  }

  resetHead(id: string) {
    if (this.head && this.head.id === id) return
    const target = this.finds(id)
    if (target) {
      // Remove orphaned entries from map and secondary structures. Collect the
      // dates whose first-of-date node we drop so we can repoint each to its
      // earliest SURVIVING node once the new head is in place — recomputing
      // mid-walk would still see the orphans (head not yet moved).
      const affectedDateIds = new Set<number>()
      let orphanCount = 0
      let orphan: Message | null = this.head
      while (orphan && orphan !== target) {
        this.map.delete(orphan.id)
        if (this.removeFromMetadata(orphan)) affectedDateIds.add(orphan.dateId)
        orphan = orphan.next
        orphanCount++
      }
      this.head = target
      target.prev = null
      this.length -= orphanCount
      for (const dateId of affectedDateIds) {
        this.recomputeFirstMessageOfDate(dateId)
      }
      this.invalidateArrayCache()
    }
  }

  resetTail(id: string) {
    if (this.tail && this.tail.id === id) return
    const target = this.finds(id)
    if (target) {
      // Remove orphaned entries from map and secondary structures. See resetHead
      // for why first-of-date repair is deferred until after the tail moves.
      const affectedDateIds = new Set<number>()
      let orphanCount = 0
      let orphan: Message | null = this.tail
      while (orphan && orphan !== target) {
        this.map.delete(orphan.id)
        if (this.removeFromMetadata(orphan)) affectedDateIds.add(orphan.dateId)
        orphan = orphan.prev
        orphanCount++
      }
      this.tail = target
      target.next = null
      this.length -= orphanCount
      for (const dateId of affectedDateIds) {
        this.recomputeFirstMessageOfDate(dateId)
      }
      this.invalidateArrayCache()
    }
  }

  canCombine(linkedList: MessageLinkedList) {
    if (linkedList.length === 0 || !linkedList.head || !linkedList.tail)
      return false
    if (
      this.contains(linkedList.tail!.id) ||
      this.contains(linkedList.head!.id) ||
      (linkedList.contains(this.head?.id ?? '') &&
        linkedList.contains(this.tail?.id ?? ''))
    ) {
      return true
    }
    // Endpoint matching above misses two segments that interleave and overlap
    // only at an INTERIOR message — neither's head/tail is shared (e.g. a
    // jump-to-message history page whose middle coincides with a reconnect's
    // latest page). Left unmerged, that shared message lives in both segments
    // as a cross-segment duplicate, and an edit (resolved through the head-most
    // segment) updates one copy while the other lingers as a stale ghost.
    // combine() unions by id, so merging on ANY shared message is lossless.
    return this.sharesMessage(linkedList)
  }

  // Whether the two chains share at least one message id. Walks the shorter
  // chain only; contains() tests linked membership, so map-only reply targets
  // (carried for preview resolution, not part of either timeline) don't count.
  private sharesMessage(linkedList: MessageLinkedList): boolean {
    const [shorter, longer] =
      this.length <= linkedList.length ? [this, linkedList] : [linkedList, this]
    let node = shorter.head
    while (node) {
      if (longer.contains(node.id)) return true
      node = node.next
    }
    return false
  }

  combine(linkedList: MessageLinkedList) {
    if (linkedList.length === 0 || !linkedList.head || !linkedList.tail) return
    if (!this.canCombine(linkedList)) return
    this.absorb(linkedList)
  }

  private invalidateArrayCache() {
    this.arrayCache = null
  }

  // Recompute the firstMessageOfDate entry for a date after a truncation/removal
  // deleted its current first node. Scans from head for the earliest surviving
  // node of that date; deletes the entry when no node of that date remains.
  private recomputeFirstMessageOfDate(dateId: number) {
    let current = this.head
    while (current) {
      if (current.dateId === dateId) {
        this.firstMessageOfDate.set(dateId, current)
        return
      }
      current = current.next
    }
    this.firstMessageOfDate.delete(dateId)
  }

  // Returns the first non-divider message (skipping unread-divider placeholders),
  // walking from head. O(divider-count) instead of materialising the whole array
  // with a .find() on every pagination step.
  firstRealMessage() {
    let current = this.head
    while (current?.id.startsWith('unread-divider-')) current = current.next
    return current ?? undefined
  }

  // Returns the internal memoised cache array; callers MUST treat it as
  // read-only (never push/splice/sort it) — mutating it corrupts the cache,
  // which is only rebuilt on the next structural mutation.
  array() {
    if (this.arrayCache) return this.arrayCache
    const messages: Message[] = []
    let current = this.head
    while (current) {
      messages.push(current)
      current = current.next
    }
    this.arrayCache = messages
    return messages
  }

  finds(id: string) {
    const found = this.map.get(id)
    if (found) {
      if (found.next || found.prev) {
        return found
      } else {
        return this.head === found && this.tail === found ? found : undefined
      }
    } else {
      return undefined
    }
  }

  contains(id: string) {
    return this.finds(id) !== undefined
  }

  isValid() {
    if (this.head && this.head.prev) {
      return false
    }
    if (this.tail && this.tail.next) {
      return false
    }
    let length = 0
    let current = this.head
    while (current) {
      if (current.prev && current.prev.next !== current) {
        return false
      }
      if (current.next && current.next.prev !== current) {
        return false
      }
      length++
      current = current.next
    }
    return length === this.length
  }
}
