<script setup lang="ts">
import { computed } from 'vue'
import FlexMessageBoxComponent from './FlexMessageBoxComponent.vue'
import FlexMessageButtonComponent from './FlexMessageButtonComponent.vue'
import FlexMessageIconComponent from './FlexMessageIconComponent.vue'
import FlexMessageImageComponent from './FlexMessageImageComponent.vue'
import FlexMessageSeparatorComponent from './FlexMessageSeparatorComponent.vue'
import FlexMessageSpanComponent from './FlexMessageSpanComponent.vue'
import FlexMessageTextComponent from './FlexMessageTextComponent.vue'
import FlexMessageVideoComponent from './FlexMessageVideoComponent.vue'
enum FlexMessageComponentType {
  Box = 'box',
  Button = 'button',
  Image = 'image',
  Video = 'video',
  Icon = 'icon',
  Text = 'text',
  Span = 'span',
  Separator = 'separator'
}
const components = {
  [FlexMessageComponentType.Box]: FlexMessageBoxComponent,
  [FlexMessageComponentType.Button]: FlexMessageButtonComponent,
  [FlexMessageComponentType.Image]: FlexMessageImageComponent,
  [FlexMessageComponentType.Video]: FlexMessageVideoComponent,
  [FlexMessageComponentType.Icon]: FlexMessageIconComponent,
  [FlexMessageComponentType.Text]: FlexMessageTextComponent,
  [FlexMessageComponentType.Span]: FlexMessageSpanComponent,
  [FlexMessageComponentType.Separator]: FlexMessageSeparatorComponent
}
/* eslint-disable @typescript-eslint/no-explicit-any */
const props = withDefaults(
  defineProps<{ content: any; roomId?: string; depth?: number }>(),
  {
    roomId: '',
    depth: 0
  }
)
/* eslint-enable @typescript-eslint/no-explicit-any */
const type = computed((): FlexMessageComponentType => props.content.type)
</script>

<template>
  <component
    :is="components[type]"
    :content="content"
    :room-id="roomId"
    :depth="depth"
  />
</template>

