<script setup lang="ts">
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { Search, X } from 'lucide-vue-next'
import { debounce, throttle } from 'throttle-debounce'
import { VList } from 'virtua/vue'
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Room from '../classes/room'
import { API } from '../enums/api'
import { SearchType } from '../enums/searchType'
import { useImkitStore } from '../stores/imkit'
import RoomCell from './folders/RoomCell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const message = ref('')
const selectedRoomIds = computed(() =>
  Object.entries(imkit.selectedRoomIdsForCreateFolder)
    .filter(([, selectedAt]) => Boolean(selectedAt))
    .map(([roomId]) => roomId)
)
const getSelectedAt = (roomId: string) =>
  imkit.selectedRoomIdsForCreateFolder[roomId]
const getSelectedTime = (roomId: string) => {
  const selectedAt = getSelectedAt(roomId)
  return selectedAt instanceof Date
    ? selectedAt.getTime()
    : Number.MAX_SAFE_INTEGER
}
// The pool "select all" is allowed to touch: exactly what's currently
// visible under the active filter/search, not the entire room universe.
// Selecting rooms that are filtered out (or merely scrolled past) is how
// someone mass-messages people they never intended to.
const visibleRooms = computed<Room[]>(() => {
  if (imkit.searchKeyword) {
    return (imkit.searchRooms[SearchType.RoomName] as Room[]) || []
  }
  return Object.values(imkit.rooms) as Room[]
})
const sortedRooms = computed<Room[]>(() =>
  [...visibleRooms.value].sort((a: Room, b: Room) => {
    const aSelected = !!getSelectedAt(a.id)
    const bSelected = !!getSelectedAt(b.id)
    if (aSelected && !bSelected) {
      return -1
    } else if (!aSelected && bSelected) {
      return 1
    } else if (aSelected && bSelected) {
      return getSelectedTime(a.id) - getSelectedTime(b.id)
    }
    return 0
  })
)
// A toggle, not a one-way select-all: once every visible room is selected,
// the same control deselects them. A select-all that can't be undone in one
// action is worse than none. There is no recipient cap on this SDK's
// batch-send endpoint today (`imkit.batchSendMessage` posts the full
// `paras` array with no client- or server-declared limit found in this
// codebase), so select-all has nothing to cap against.
const allVisibleSelected = computed(
  () =>
    visibleRooms.value.length > 0 &&
    visibleRooms.value.every((room) => !!getSelectedAt(room.id))
)
const toggleSelectAll = () => {
  if (allVisibleSelected.value) {
    imkit.$patch((state) => {
      for (const room of visibleRooms.value) {
        delete state.selectedRoomIdsForCreateFolder[room.id]
      }
    })
    return
  }
  const additions: Record<string, Date> = {}
  for (const room of visibleRooms.value) {
    if (!getSelectedAt(room.id)) additions[room.id] = new Date()
  }
  imkit.mergeInto('selectedRoomIdsForCreateFolder', additions)
}
const isValid = computed(
  () => message.value.trim().length > 0 && selectedRoomIds.value.length > 0
)
const searchKeyword = ref('')
const isCompositting = ref(false)
const searchRooms = async () => {
  if (isCompositting.value) return
  if (searchKeyword.value !== imkit.searchKeyword) {
    if (searchKeyword.value) {
      imkit.searchRoomsByKeyword(searchKeyword.value)
    } else {
      imkit.$patch({
        searchKeyword: ''
      })
    }
  }
}
const throttleSearchRooms = throttle(1000, searchRooms)
const debounceSearchRooms = debounce(500, throttleSearchRooms, {
  atBegin: false
})
let sessionReset = false
const stopSearchWatch = watch(searchKeyword, () => {
  if (sessionReset) return
  debounceSearchRooms()
})
const isRequesting = computed(() => !!imkit.isRequesting[API.Search])
const resetSession = () => {
  if (sessionReset) return
  sessionReset = true
  stopSearchWatch()
  debounceSearchRooms.cancel()
  throttleSearchRooms.cancel()
  searchKeyword.value = ''
  imkit.$patch((state) => {
    state.selectedRoomIdsForCreateFolder = {}
    state.searchKeyword = ''
  })
}
const cancel = () => {
  resetSession()
  vfm.closeAll()
}
const submit = async () => {
  const paras = selectedRoomIds.value.map((roomId) => ({ room: roomId }))
  const text = message.value.trim()
  resetSession()
  vfm.closeAll()
  try {
    await imkit.batchSendMessage({
      message: text,
      messageType: 'text',
      paras
    })
  } catch (error) {
    // batchSendMessage POSTs /messages/batch and throws on failure. The @click
    // handler fires this unawaited and then closes the modal, so a rejection
    // would become an unhandled rejection with the modal already gone. Swallow
    // it (logged, not surfaced — no toast infra in this SDK, same as
    // useComposer's send-failure path); user-facing feedback is a deferred
    // sibling.
    console.error('Failed to batch send messages', error)
  }
}
onBeforeUnmount(resetSession)
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg shadow-raised border border-border flex h-[min(720px,calc(var(--imkit-viewport-height)_-_2rem))] max-h-[min(720px,calc(var(--imkit-viewport-height)_-_2rem))] w-[calc(100vw-2rem)] max-w-[420px] flex-col overflow-hidden shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
    @before-close="resetSession"
    @closed="resetSession"
  >
    <!--
      No close ✕. ConfirmDialogShell dropped one deliberately and the other
      thirteen dialogs follow it, so this was the only dialog in the app with a
      ✕ in the corner. Escape and overlay-click still dismiss — vue-final-modal
      defaults both to true and nothing here overrides them — and 取消 in the
      footer is the explicit route.
    -->
    <header
      class="flex shrink-0 items-start gap-3 border-b border-border px-5 py-4"
    >
      <div class="min-w-0">
        <h1 class="text-xl font-semibold text-content">
          {{ $t('massTexting') }}
        </h1>
        <p class="mt-1 text-xs text-content-muted">
          {{ $t('massTextingDescription') }}
        </p>
      </div>
    </header>

    <div class="flex min-h-0 flex-1 flex-col gap-4 overflow-hidden px-5 py-4">
      <label for="mass-texting-message" class="flex shrink-0 flex-col gap-1.5">
        <span class="text-xs font-semibold text-content-muted">
          {{ $t('messageContent') }}
        </span>
        <textarea
          id="mass-texting-message"
          v-model="message"
          rows="3"
          class="w-full resize-none rounded-md border border-border bg-surface px-3 py-2.5 text-base text-content placeholder-content-subtle transition-colors outline-none focus-visible:border-accent focus-visible:ring-2 focus-visible:ring-accent-subtle"
          :placeholder="$t('inputMessage')"
        />
      </label>

      <section class="flex min-h-0 flex-1 flex-col gap-2">
        <div class="flex shrink-0 items-center justify-between gap-3">
          <h2
            id="mass-texting-recipients-label"
            class="text-xs font-semibold text-content-muted"
          >
            <label for="mass-texting-search">
              {{ $t('recipientRooms') }}
            </label>
          </h2>
          <div class="flex items-center gap-3">
            <button
              type="button"
              data-testid="mass-texting-select-all"
              class="cursor-pointer text-xs font-semibold text-accent-vivid hover:underline disabled:cursor-not-allowed disabled:text-content-faint disabled:no-underline"
              :disabled="visibleRooms.length === 0"
              @click="toggleSelectAll"
            >
              {{
                allVisibleSelected
                  ? imkit.searchKeyword
                    ? $t('deselectAllFiltered')
                    : $t('deselectAll')
                  : imkit.searchKeyword
                    ? $t('selectAllFiltered')
                    : $t('selectAll')
              }}
            </button>
            <span class="text-xs text-content-muted">
              {{ $t('selectedCount', { n: selectedRoomIds.length }) }}
            </span>
          </div>
        </div>

        <div
          class="flex h-10 shrink-0 items-center gap-2 rounded-md border border-border bg-surface px-3 focus-within:border-accent focus-within:ring-2 focus-within:ring-accent-subtle"
        >
          <Search :size="18" class="shrink-0 text-content-subtle" />
          <input
            id="mass-texting-search"
            v-model="searchKeyword"
            class="min-w-0 flex-1 bg-transparent text-base text-content placeholder-content-subtle outline-none"
            aria-labelledby="mass-texting-recipients-label"
            :placeholder="$t('search')"
            @compositionstart="isCompositting = true"
            @compositionend="isCompositting = false"
            @blur="isCompositting = false"
          />
          <button
            v-if="searchKeyword"
            type="button"
            class="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-md text-content-muted transition-colors hover:bg-surface-hover hover:text-content focus-visible:ring-2 focus-visible:ring-accent-vivid focus-visible:outline-none"
            :aria-label="$t('clearSearch')"
            @click="
              () => {
                debounceSearchRooms.cancel({ upcomingOnly: true })
                searchKeyword = ''
                throttleSearchRooms()
              }
            "
          >
            <X :size="18" />
          </button>
        </div>

        <div
          data-testid="mass-texting-recipient-list"
          class="relative flex min-h-0 flex-1 overflow-hidden rounded-md border border-border"
        >
          <div
            v-if="isRequesting"
            class="absolute inset-0 z-10 flex flex-col gap-1 overflow-hidden bg-surface"
          >
            <div v-for="i in 10" :key="i" class="flex gap-3 p-2">
              <div
                class="loading h-[34px] w-[34px] rounded-lg bg-surface-muted"
              />
              <div class="flex grow flex-col justify-center gap-2">
                <div class="loading h-3 w-full rounded-md bg-surface-muted" />
                <div class="loading h-3 w-4/5 rounded-md bg-surface-muted" />
              </div>
            </div>
          </div>
          <VList
            v-slot="{ item }"
            :data="sortedRooms"
            :item-size="44"
            class="min-h-0 flex-1 overflow-auto"
            list-class="flex flex-col gap-1.5"
          >
            <RoomCell :source="item" />
          </VList>
        </div>
      </section>
    </div>

    <footer
      data-testid="mass-texting-footer"
      class="flex shrink-0 flex-wrap items-center justify-between gap-2 border-t border-border px-5 py-4"
    >
      <span
        role="status"
        data-testid="mass-texting-footer-count"
        class="mr-auto text-xs text-content-muted"
      >
        {{ $t('selectedCount', { n: selectedRoomIds.length }) }}
      </span>
      <div class="ml-auto flex items-center gap-2">
        <!--
          ConfirmDialogShell's own pair, verbatim: a `surface-muted` secondary
          and a `bg-accent` primary at `font-medium`. This was an OUTLINED
          cancel in `border-strong` beside a `font-semibold` confirm, which is
          a different button family from every other dialog's.
        -->
        <button
          type="button"
          class="inline-flex h-10 w-auto cursor-pointer items-center justify-center rounded-md bg-surface-muted px-4 text-base font-medium text-content transition-colors hover:bg-border focus-visible:ring-2 focus-visible:ring-accent-vivid focus-visible:outline-none"
          @click="cancel"
        >
          {{ $t('cancel') }}
        </button>
        <button
          type="button"
          class="inline-flex h-10 w-auto cursor-pointer items-center justify-center rounded-md bg-accent px-4 text-base font-medium text-white transition-colors hover:bg-accent-hover focus-visible:ring-2 focus-visible:ring-accent-vivid focus-visible:outline-none disabled:cursor-not-allowed disabled:bg-surface-muted disabled:text-content-faint"
          :disabled="!isValid"
          @click="submit"
        >
          {{ $t('sendMessage') }}
        </button>
      </div>
    </footer>
  </vue-final-modal>
</template>
<style scoped>
@keyframes bg {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.loading {
  animation: bg 2s infinite;
}
</style>
