import { twMerge } from 'tailwind-merge'

export type ClassValue =
  string | null | undefined | ClassValue[] | Record<string, boolean>

const hasNonWhitespace = (value: string): boolean => value.trim().length > 0

const toStringClass = (value: ClassValue): string => {
  if (typeof value === 'string') return value
  if (Array.isArray(value)) {
    return value
      .map((item) => toStringClass(item as ClassValue))
      .filter((item) => hasNonWhitespace(item))
      .join(' ')
  }
  if (value && typeof value === 'object') {
    return Object.entries(value as Record<string, boolean>)
      .filter(([, present]) => Boolean(present))
      .map(([className]) => className)
      .join(' ')
  }
  return ''
}

// twMerge resolves Tailwind utility conflicts so the LAST class wins, making the
// cn(defaults, className, props.class) override pattern in the UI primitives work:
// without it the joined string emits both the base and the override, and CSS source
// order (not argument order) decides — silently ignoring or flickering the override.
export const cn = (...inputs: ClassValue[]): string =>
  twMerge(
    inputs
      .map((input) => toStringClass(input))
      .filter((value) => hasNonWhitespace(value))
      .join(' ')
  )
