<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const props = defineProps<{
  memberIdToMoveOut: string
  roomId: string
}>()

const vfm = useVfm()
const imkit = useImkitStore()

const users = computed(() => imkit.users)
const showError = ref(false)
const isLoading = ref(false)

const cancelMoveOut = () => {
  vfm.closeAll()
}

const executeMoveOut = async () => {
  if (props.memberIdToMoveOut) {
    isLoading.value = true
    try {
      await imkit.removeMembers({
        roomId: props.roomId,
        uids: [props.memberIdToMoveOut]
      })
      vfm.closeAll()
    } catch (error) {
      console.error('Failed to remove member:', error)
      showError.value = true
    } finally {
      isLoading.value = false
    }
  }
}

const closeError = () => {
  showError.value = false
  vfm.closeAll()
}

// Single root, see BlockUserConfirmModal.vue's comment.
const onConfirm = () => (showError.value ? closeError() : executeMoveOut())
</script>

<template>
  <ConfirmDialogShell
    :title="
      showError
        ? $t('kickOutErrorTitle')
        : $t('kickOutConfirmTitle', [users[memberIdToMoveOut]?.nickname])
    "
    :cancel-label="showError ? undefined : $t('cancel')"
    :confirm-label="showError ? $t('confirm') : $t('kickOutGroup')"
    :loading="!showError && isLoading"
    @cancel="cancelMoveOut"
    @confirm="onConfirm"
  >
    {{ showError ? $t('kickOutErrorDesc') : $t('kickOutConfirmTip') }}
  </ConfirmDialogShell>
</template>
