import { computed, getCurrentScope, onScopeDispose, ref } from 'vue'
import type Message from '../classes/message'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import {
  collectRoomMediaItems,
  getRoomMediaFileId,
  type RoomMediaItem
} from '../utils/roomMediaList'
import { useRoomContentMediaNavigation } from './useRoomContentMediaNavigation'

const isFileApiNavigationEnabled = () => {
  try {
    return getConfig().settings.roomContentEnabled !== false
  } catch {
    return false
  }
}

export function useRoomMediaLightbox(getMessage: () => Message) {
  const imkit = useImkitStore()
  const open = ref(false)
  const mediaIndex = ref(0)
  const mediaItems = ref<RoomMediaItem[]>([])
  const navigationRoomId = ref<string>()
  const roomContentNavigation = useRoomContentMediaNavigation(
    () => navigationRoomId.value,
    () => [getMessage()]
  )
  const firstOlderApiFileId = ref<string | null>(null)
  let selectionGeneration = 0
  let fileApiSelectionRequest: Promise<boolean> | null = null
  let selectedFileId: string | null = null
  const activeMediaItem = computed(
    () => mediaItems.value[mediaIndex.value] ?? null
  )
  // Local navigation preserves repeated or not-yet-indexed image occurrences.
  // At its beginning, older API entries are still reachable without eagerly scanning
  // history when the user opens an image.
  const nextOlderApiMedia = computed(() => {
    const anchor = activeMediaItem.value
    if (!anchor || imkit.chatRoomContentMediaRoomId !== navigationRoomId.value)
      return null
    const seen = new Set(mediaItems.value.map(getRoomMediaFileId))
    const ordered = roomContentNavigation.orderedMedia.value
    const anchorIndex = ordered.findIndex(
      (file) => file._id === getRoomMediaFileId(anchor)
    )
    return (
      ordered.findLast((file, index) => {
        if (seen.has(file._id)) return false
        if (anchorIndex >= 0) return index < anchorIndex
        const time = roomContentNavigation.getMediaCreatedAt(file)
        return (
          time < anchor.createdAt ||
          (time === anchor.createdAt &&
            typeof file.messageID === 'string' &&
            file.messageID < anchor.messageId)
        )
      }) ?? null
    )
  })
  const hasReachedLocalBoundary = computed(() => {
    const anchor = activeMediaItem.value
    return Boolean(
      anchor &&
      roomContentNavigation.orderedMedia.value.some((file) => {
        const time = roomContentNavigation.getMediaCreatedAt(file)
        return (
          file._id === getRoomMediaFileId(anchor) ||
          time < anchor.createdAt ||
          (time === anchor.createdAt &&
            (file.messageID ?? '') <= anchor.messageId)
        )
      })
    )
  })
  const canLoadOlderApiMedia = computed(
    () =>
      isFileApiNavigationEnabled() &&
      Boolean(navigationRoomId.value) &&
      (imkit.chatRoomContentMediaRoomId !== navigationRoomId.value ||
        Boolean(nextOlderApiMedia.value) ||
        imkit.chatRoomContentMediaHasMore)
  )
  const mediaCount = computed(() =>
    roomContentNavigation.selectedMedia.value
      ? Math.max(
          roomContentNavigation.mediaCount.value,
          firstOlderApiFileId.value ? mediaItems.value.length + 1 : 0
        )
      : Math.max(
          mediaItems.value.length,
          canLoadOlderApiMedia.value ? mediaItems.value.length + 1 : 0
        )
  )
  const canNavigatePrevious = computed(() =>
    roomContentNavigation.selectedMedia.value
      ? roomContentNavigation.canNavigatePrevious.value
      : mediaIndex.value >= 0 &&
        (mediaIndex.value > 0 || canLoadOlderApiMedia.value)
  )
  const canNavigateNext = computed(() =>
    roomContentNavigation.selectedMedia.value
      ? firstOlderApiFileId.value ===
          roomContentNavigation.selectedMedia.value._id ||
        roomContentNavigation.canNavigateNext.value
      : mediaIndex.value >= 0 && mediaIndex.value < mediaItems.value.length - 1
  )

  const findRoomContentMedia = (fileId: string) =>
    imkit.chatRoomContentMedia.find((item) => item._id === fileId) ?? null

  const loadFileApiSelection = async (
    roomId: string,
    fileId: string,
    generation: number
  ): Promise<boolean> => {
    const requiredFileIds = mediaItems.value.map(getRoomMediaFileId)
    // The File API has one row per file. Keep occurrence-based navigation for
    // local uploads or repeated references that it cannot represent.
    if (
      requiredFileIds.some((id) => !id) ||
      new Set(requiredFileIds).size !== requiredFileIds.length
    )
      return false
    const selectedItem = mediaItems.value.find(
      (item) => getRoomMediaFileId(item) === fileId
    )
    const selectedMessageFileIds = mediaItems.value
      .filter((item) => item.messageId === selectedItem?.messageId)
      .map(getRoomMediaFileId)
    const hasFiles = (fileIds: (string | null)[]) => {
      const availableIds = new Set(
        imkit.chatRoomContentMedia.map((item) => item._id)
      )
      return fileIds.every((id) => id !== null && availableIds.has(id))
    }
    if (
      imkit.chatRoomContentMediaRoomId !== roomId ||
      imkit.chatRoomContentMediaLoading
    ) {
      await imkit.fetchRoomContentMedia({ roomId })
    }

    let matched = findRoomContentMedia(fileId)
    while (
      (!matched || !hasFiles(selectedMessageFileIds)) &&
      open.value &&
      generation === selectionGeneration &&
      imkit.chatRoomContentMediaRoomId === roomId &&
      imkit.chatRoomContentMediaHasMore
    ) {
      const previousOffset = imkit.chatRoomContentMediaOffset
      await imkit.fetchRoomContentMedia({ roomId, loadMore: true })
      matched = findRoomContentMedia(fileId)
      if (imkit.chatRoomContentMediaOffset <= previousOffset) break
    }

    if (
      !matched ||
      !open.value ||
      generation !== selectionGeneration ||
      navigationRoomId.value !== roomId
    ) {
      return false
    }
    // A totalCount is not evidence that the matching images have arrived.
    // Switching with only part of a group loaded skips its missing pictures.
    // Missing media from other messages can be newly sent and not indexed yet.
    // Keep local navigation; searching older pages cannot repair that lag.
    if (!hasFiles(requiredFileIds)) return false
    roomContentNavigation.selectMedia(matched)
    return true
  }

  const startFileApiSelection = (
    roomId: string,
    fileId: string,
    generation: number
  ) => {
    const request = loadFileApiSelection(roomId, fileId, generation).catch(
      (error) => {
        if (generation === selectionGeneration) {
          console.error('[MediaLightbox] failed to load room media:', error)
        }
        return false
      }
    )
    fileApiSelectionRequest = request
    return request
  }

  const openMessageMedia = (matches: (item: RoomMediaItem) => boolean) => {
    const message = getMessage()
    const loadedMessages =
      imkit.messageMultiLists?.get(message.roomId)?.main?.array() ?? []
    const nextMediaItems = collectRoomMediaItems(
      loadedMessages.length > 0 ? loadedMessages : [message]
    )
    const nextIndex = nextMediaItems.findIndex(
      (item) => item.messageId === message.id && matches(item)
    )
    if (nextIndex < 0) return

    firstOlderApiFileId.value = null
    mediaItems.value = nextMediaItems
    mediaIndex.value = nextIndex
    roomContentNavigation.selectMedia(null)
    navigationRoomId.value = message.roomId
    open.value = true

    selectionGeneration += 1
    const generation = selectionGeneration
    selectedFileId = getRoomMediaFileId(nextMediaItems[nextIndex])
    if (!selectedFileId || !isFileApiNavigationEnabled()) {
      fileApiSelectionRequest = null
      return
    }
    startFileApiSelection(message.roomId, selectedFileId, generation)
  }

  const navigateLoadedMessages = (direction: 'previous' | 'next') => {
    const nextIndex = mediaIndex.value + (direction === 'next' ? 1 : -1)
    if (nextIndex < 0 || nextIndex >= mediaItems.value.length) return
    mediaIndex.value = nextIndex
    selectedFileId = getRoomMediaFileId(mediaItems.value[nextIndex])
  }

  const loadOlderApiMedia = async (generation: number) => {
    const roomId = navigationRoomId.value
    const sessionEpoch = imkit.sessionEpoch
    if (!roomId) return
    // Occurrence-only media may never initialize the File API on open.
    // Fetch its first page only when the user reaches the local boundary.
    if (
      imkit.chatRoomContentMediaRoomId !== roomId ||
      imkit.chatRoomContentMediaLoading
    ) {
      await imkit.fetchRoomContentMedia({ roomId })
    }
    while (
      open.value &&
      generation === selectionGeneration &&
      navigationRoomId.value === roomId &&
      imkit.sessionEpoch === sessionEpoch &&
      imkit.chatRoomContentMediaRoomId === roomId
    ) {
      if (
        imkit.chatRoomContentMediaHasMore &&
        (!hasReachedLocalBoundary.value || !nextOlderApiMedia.value)
      ) {
        const offset = imkit.chatRoomContentMediaOffset
        await imkit.fetchRoomContentMedia({ roomId, loadMore: true })
        if (imkit.chatRoomContentMediaOffset <= offset) return
        continue
      }
      const next = nextOlderApiMedia.value
      if (next) {
        firstOlderApiFileId.value = next._id
        roomContentNavigation.selectMedia(next)
        return
      }
      return
    }
  }

  const navigateMedia = async (direction: 'previous' | 'next') => {
    const generation = selectionGeneration
    await fileApiSelectionRequest
    if (!open.value || generation !== selectionGeneration) return
    if (!roomContentNavigation.selectedMedia.value) {
      const localIndex = mediaIndex.value + (direction === 'next' ? 1 : -1)
      if (localIndex >= 0 && localIndex < mediaItems.value.length) {
        navigateLoadedMessages(direction)
        return
      }
    }
    if (
      !roomContentNavigation.selectedMedia.value &&
      direction === 'previous' &&
      canLoadOlderApiMedia.value
    ) {
      await loadOlderApiMedia(generation)
      return
    }
    if (roomContentNavigation.selectedMedia.value) {
      if (
        direction === 'next' &&
        roomContentNavigation.selectedMedia.value._id ===
          firstOlderApiFileId.value
      ) {
        roomContentNavigation.selectMedia(null)
        mediaIndex.value = 0
        selectedFileId = getRoomMediaFileId(mediaItems.value[0])
        return
      }
      if (direction === 'previous') {
        await roomContentNavigation.previousMedia()
      } else {
        await roomContentNavigation.nextMedia()
      }
      return
    }
    navigateLoadedMessages(direction)
  }

  const previousMedia = () => navigateMedia('previous')
  const nextMedia = () => navigateMedia('next')

  const close = () => {
    selectionGeneration += 1
    firstOlderApiFileId.value = null
    fileApiSelectionRequest = null
    selectedFileId = null
    navigationRoomId.value = undefined
    open.value = false
    mediaIndex.value = -1
    roomContentNavigation.selectMedia(null)
  }

  if (getCurrentScope()) {
    onScopeDispose(() => {
      selectionGeneration += 1
      fileApiSelectionRequest = null
      selectedFileId = null
      navigationRoomId.value = undefined
      open.value = false
    })
  }

  return {
    open,
    mediaIndex,
    mediaItems,
    activeMediaItem,
    selectedMedia: roomContentNavigation.selectedMedia,
    mediaCount,
    canNavigatePrevious,
    canNavigateNext,
    openMessageMedia,
    previousMedia,
    nextMedia,
    close
  }
}
