import {
  Copy,
  Pencil,
  Reply,
  RotateCcw,
  Trash2,
  type LucideIcon
} from 'lucide-vue-next'
import { computed, toValue, type MaybeRefOrGetter } from 'vue'

export type ActionType =
  | 'reply'
  | 'copy'
  | 'translate'
  | 'edit'
  | 'unsend'
  | 'delete'
  /**
   * Opens the reaction sheet. Its only other entry point is a 500ms
   * long-press bound to `touchstart` in ReactionList.vue, so before this
   * item existed the sheet was unreachable with a mouse — the whole panel
   * had no desktop trigger at all.
   *
   * Assembled next to the react entry in MessageActionButtons.vue rather
   * than here, because like that one it is gated on message STATE (are there
   * any reactions to look at) rather than on a permission.
   */
  | 'viewReactions'

export interface ActionItem {
  type: ActionType
  icon: LucideIcon
  labelKey: string
  danger?: boolean
}

/**
 * A fixed group of related items (e.g. "primary" reply/copy/edit actions,
 * vs. the standalone "delete" action). Groups may be empty — visibility is
 * expressed by omitting an item from a group's `items`, not by a `visible`
 * flag on the item — and it is the caller's job (via `flattenMenuGroups`) to
 * only draw a separator between two groups that both have items.
 */
export interface ActionGroup {
  key: string
  items: ActionItem[]
}

export interface MessageActionOptions {
  canReply: MaybeRefOrGetter<boolean>
  canCopy: MaybeRefOrGetter<boolean>
  canTranslate?: MaybeRefOrGetter<boolean> // TODO: 實作翻譯功能
  canEdit: MaybeRefOrGetter<boolean>
  isOutgoing: MaybeRefOrGetter<boolean>
  isSuperuser: MaybeRefOrGetter<boolean>
  isGroupRoom: MaybeRefOrGetter<boolean>
}

export function useMessageActionItems(options: MessageActionOptions) {
  return computed<ActionGroup[]>(() => {
    const canReply = toValue(options.canReply)
    const canCopy = toValue(options.canCopy)
    const canEdit = toValue(options.canEdit)
    const isOutgoing = toValue(options.isOutgoing)

    const primaryItems: ActionItem[] = []
    if (canReply) {
      primaryItems.push({ type: 'reply', icon: Reply, labelKey: 'reply' })
    }
    if (canCopy) {
      primaryItems.push({ type: 'copy', icon: Copy, labelKey: 'copy' })
    }
    if (canEdit) {
      primaryItems.push({ type: 'edit', icon: Pencil, labelKey: 'edit' })
    }

    return [
      {
        key: 'primary',
        items: primaryItems
      },
      // Unsend and delete share one group and both read as danger. They are
      // the two irreversible actions, so grouping them puts every destructive
      // choice behind the same separator instead of implying unsend is a
      // lesser sibling of copy/edit. Unsend was previously its own group with
      // no danger flag, which rendered a red delete beside a black unsend
      // even though both destroy the message.
      {
        key: 'destructive',
        items: [
          ...(isOutgoing
            ? [
                {
                  type: 'unsend' as const,
                  // RotateCcw, not UndoDot: the artifact's 收回訊息 glyph is
                  // this exact path (a counter-clockwise circular arrow).
                  // Note it is also the retry button's glyph in
                  // MessageActionButtons, but that one only appears on a
                  // FAILED outgoing message, where no unsend item exists, so
                  // the two never share a surface.
                  icon: RotateCcw,
                  labelKey: 'unsend',
                  danger: true
                }
              ]
            : []),
          {
            type: 'delete' as const,
            icon: Trash2,
            labelKey: 'delete',
            danger: true
          }
        ]
      }
    ]
  })
}

export type MenuEntry<T> = { kind: 'separator' } | { kind: 'item'; item: T }

/**
 * Flattens a sequence of fixed groups into a render list, inserting a
 * separator only on the boundary between two groups that both have at least
 * one item. A separator is therefore structurally incapable of rendering
 * first, last, or beside another separator: it never exists as an element in
 * its own right, only as the gap between two non-empty groups.
 *
 * This replaces the previous scheme, which emitted one separator
 * unconditionally after a fixed "react" group and another per-item via a
 * `dividerBefore` flag on the next fixed item. Whenever the group in between
 * (reply/copy/edit) was entirely hidden by permissions, both separators
 * still rendered — back to back, with nothing between them.
 */
export function flattenMenuGroups<T>(groups: { items: T[] }[]): MenuEntry<T>[] {
  const nonEmptyGroups = groups.filter((group) => group.items.length > 0)
  const entries: MenuEntry<T>[] = []
  nonEmptyGroups.forEach((group, index) => {
    if (index > 0) {
      entries.push({ kind: 'separator' })
    }
    group.items.forEach((item) => entries.push({ kind: 'item', item }))
  })
  return entries
}
