dayjs.extend(utc)
dayjs.extend(timezone)

const safeGetImkitStore = () => {
  try {
    return getImkitStore()
  } catch {
    return null
  }
}

// Shared parsing helpers for the media-bearing message types. ImageMessage and
// MixedMessage parse images identically; TextMessage and MixedMessage parse
// urls identically. Centralizing keeps the four constructors in lockstep.

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const parseImages = (raw: any): IMImage[] => {
  const { images, width, height, thumbnailUrl, originalUrl } = raw
  if (images && images.length > 0) {
    return images.filter(
      (image: IMImage) => image.thumbnailUrl || image.originalUrl
    )
  }
  if (originalUrl || thumbnailUrl) {
    return [
      {
        id: originalUrl,
        width,
        height,
        thumbnailUrl,
        originalUrl
      }
    ]
  }
  return []
}

const parseUrls = (text: string): string[] => {
  try {
    return Array.from(
      new Set(
        TextMessage.autolinker
          .parse(text)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .map((match: any) =>
            typeof match.getUrl === 'function' ? match.getUrl() : ''
          )
          .filter((url: string) => url !== '')
      )
    )
  } catch (error) {
    console.log(text)
    console.error(error)
    return []
  }
}

export enum MessageType {
  Text = 'text',
  Image = 'image',
  Mixed = 'mixed',
  Sticker = 'sticker',
  Video = 'video',
  File = 'file',
  Template = 'template',
  Flex = 'flex',
  Location = 'location',
  Audio = 'audio',
  Recall = 'recall',
  JoinRoom = 'joinRoom',
  LeaveRoom = 'leaveRoom',
  AddMember = 'addMember',
  DeleteMember = 'deleteMember',
  AddMembers = 'addMembers',
  Announcement = 'announcement',
  Typing = 'typing',
  AIStreaming = 'ai_streaming'
}
export interface Reaction {
  client: string
  reaction: string
}

export enum MessageStatus {
  Sending = 'sending',
  Delivered = 'delivered',
  Failed = 'failed'
}
export default class Message {
  id: string
  roomId: string
  senderId: string
  senderNickname: string
  type: MessageType
  status: MessageStatus
  createdAt: number
  updatedAt: number
  editedAt: string | null
  groupId: string
  dateId: number
  reactions: Reaction[]

  prev: Message | null = null
  next: Message | null = null

  payload: Record<string, unknown> | null = null

  _string(uid: string, users: { [uid: string]: User }, isGroup = true): string {
    let item = i18n.global.t('message')
    const senderNickname = users[this.senderId]?.nickname ?? ''
    switch (this.type) {
      case MessageType.Image:
        item = i18n.global.t('image')
        break
      case MessageType.Mixed:
        item = i18n.global.t('image')
        break
      case MessageType.Sticker:
        item = i18n.global.t('sticker')
        break
      case MessageType.Video:
        item = i18n.global.t('video')
        break
      case MessageType.File:
        item = i18n.global.t('file')
        break
      case MessageType.Location:
        item = i18n.global.t('location')
        break
      case MessageType.Audio:
        item = i18n.global.t('audio')
        break
      case MessageType.Recall:
        if (this.senderId === uid) {
          return i18n.global.t('youUnsentMessage')
        }
        return i18n.global.t('someoneUnsentMessage', [senderNickname])
      case MessageType.JoinRoom:
        return i18n.global.t('someoneJoinedTheChat', [senderNickname])
      case MessageType.LeaveRoom:
        return i18n.global.t('someoneLeftTheChat', [senderNickname])
      case MessageType.AddMember:
      case MessageType.AddMembers: {
        const memberNames =
          this instanceof SystemMessage
            ? this.members.map((member) => member.nickname).join(', ')
            : ''
        return i18n.global.t('someoneInvited', [senderNickname, memberNames])
      }
      case MessageType.DeleteMember: {
        const memberNames =
          this instanceof SystemMessage
            ? this.members.map((member) => member.nickname).join(', ')
            : ''
        return i18n.global.t('someoneKicked', [senderNickname, memberNames])
      }
      case MessageType.Announcement:
        if (this instanceof TextMessage) {
          return this.text
        }
        return i18n.global.t('message')
      default:
        break
    }
    const itemLower = item.toLowerCase()
    if (this.senderId === uid) {
      return i18n.global.t('youSent', [itemLower])
    }
    // In a 1-on-1 room the room title already shows the other person, so the
    // sender name would be redundant in the preview. Only groups keep it.
    return isGroup
      ? i18n.global.t('someoneSent', [senderNickname, itemLower])
      : i18n.global.t('sentYouItem', [itemLower])
  }

  get string(): string {
    return this._string(getUid(), safeGetImkitStore()?.users ?? {})
  }

  /**
   * Last-message preview that drops the sender name in 1-on-1 rooms.
   * Callers pass the owning room's type so the lookup stays reliable even when
   * the room-list payload omits a roomId on the message.
   */
  previewString(isGroup: boolean): string {
    return this._string(getUid(), safeGetImkitStore()?.users ?? {}, isGroup)
  }

  /**
   * Label for the "latest message" banner inside an open room. It mirrors the
   * room-list preview, except group text/mixed messages — whose preview is the
   * raw body with no sender name — get a "Name: " prefix so it's clear who
   * spoke. Every other type's preview already names the sender (or is a 1-on-1,
   * which shows no name by design), so no prefix is added.
   */
  bannerLabel(isGroup: boolean): string {
    const body = this.previewString(isGroup)
    return isGroup &&
      (this.type === MessageType.Text || this.type === MessageType.Mixed)
      ? `${this.senderNickname}: ${body}`
      : body
  }

  get isIncoming(): boolean {
    return !this.isOutgoing
  }

  get isOutgoing(): boolean {
    const rooms = safeGetImkitStore()?.rooms ?? {}
    const uid = getUid()
    return !!(
      this.senderId === uid ||
      rooms[this.roomId]?.isOutgoingGroupSender[this.senderId]
    )
  }

  get isSystem(): boolean {
    return new Set([
      MessageType.Recall,
      MessageType.JoinRoom,
      MessageType.LeaveRoom,
      MessageType.AddMember,
      MessageType.DeleteMember,
      MessageType.AddMembers,
      MessageType.Announcement
    ]).has(this.type)
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    const {
      _id: id,
      room: roomId,
      sender,
      messageType: type,
      createdAtMS: createdAt,
      updatedAtMS: updatedAt,
      editedAt = null,
      extra,
      reactions
    } = raw
    this.id = id
    this.roomId = roomId
    this.senderId = sender?._id || ''
    this.senderNickname = sender?.nickname || ''
    if (type === 'line') {
      this.type = extra?.type ?? type
    } else {
      this.type = type
    }
    this.status = MessageStatus.Delivered
    this.createdAt = createdAt
    this.updatedAt = updatedAt
    this.editedAt = editedAt
    this.groupId = `${dayjs(createdAt).startOf('minute').unix()}-${
      this.senderId
    }`
    this.dateId = dayjs.tz(createdAt).startOf('day').unix()
    this.reactions = reactions ?? []
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static create(raw: any): Message | null {
    if (!raw) {
      return null
    }
    switch (raw.messageType) {
      case MessageType.Text:
        return new TextMessage(raw)
      case MessageType.Image:
        return new ImageMessage(raw)
      case MessageType.Mixed:
        return new MixedMessage(raw)
      case MessageType.Sticker:
        return new StickerMessage(raw)
      case MessageType.Video:
        return new VideoMessage(raw)
      case MessageType.File:
        return new FileMessage(raw)
      case MessageType.Template:
        return new TemplateMessage(raw)
      case MessageType.Flex:
        return new FlexMessage(raw)
      case MessageType.Location:
        return new LocationMessage(raw)
      case MessageType.Audio:
        return new AudioMessage(raw)
      case MessageType.AIStreaming:
        return new AIStreamingMessage(raw)
      case MessageType.Announcement:
        return new TextMessage(raw)
      case MessageType.AddMember:
        return new SystemMessage(raw)
      case MessageType.DeleteMember:
        return new SystemMessage(raw)
      case MessageType.AddMembers:
        return new SystemMessage(raw)
      case 'line': {
        if (typeof raw.extra === 'string') {
          try {
            raw.extra = JSON.parse(raw.extra)
          } catch {
            return new Message(raw)
          }
        }
        if (!raw.extra || typeof raw.extra !== 'object') {
          return new Message(raw)
        }
        switch (raw.extra.type) {
          case MessageType.Sticker:
            return new StickerMessage(raw)
          default:
            return new Message(raw)
        }
      }
      default:
        return new Message(raw)
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  static createReactive(raw: any): Message | null {
    // A malformed payload can make a subclass constructor throw (e.g. a sticker
    // with no `extra`). Callers build whole message pages by mapping over a list
    // of payloads, so an escaping throw blanks the entire page. Absorb it and
    // return null — the contract every caller already handles — so one bad
    // message is skipped instead of taking down the rest.
    try {
      const message = Message.create(raw)
      return message ? reactive(message) : null
    } catch (error) {
      console.error('Failed to create message from payload', error, raw)
      return null
    }
  }

  static fromPayload(
    payload: Record<string, unknown>,
    uid: string
  ): Message | null {
    const timestamp = Date.now()
    const { roomId: room } = payload
    const raw = {
      _id: uuidv4(),
      room,
      sender: { _id: uid },
      createdAtMS: timestamp,
      updatedAtMS: timestamp,
      ...payload
    }
    const message = Message.createReactive(raw)
    if (message) {
      message.payload = payload
    }
    return message
  }
}

export class TextMessage extends Message {
  text: string
  translatedText: string | null
  replyId: string | null
  urls: string[]

  get string(): string {
    const $ = cheerio.load(this.html)
    return $.text()
  }

  previewString(): string {
    return this.string
  }

  static autolinker: Autolinker = new Autolinker({
    className: 'underline',
    email: false,
    phone: true,
    stripPrefix: false,
    stripTrailingSlash: false,
    mention: 'imkit',
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    replaceFn: function (match: any) {
      switch (match.getType()) {
        case 'url':
          return true
        case 'phone': {
          // Autolinker's default phone anchors reuse newWindow and get
          // target="_blank", which is wrong for tel: dialer links. Emit the
          // anchor ourselves without a browsing-context target.
          const href = match.getAnchorHref()
          const text = match.getAnchorText()
          return `<a href="${escapeHtml(href)}" class="underline underline-phone">${escapeHtml(text)}</a>`
        }
        case 'mention': {
          const uid = match.getMention()
          const user = safeGetImkitStore()?.users[uid]
          if (user) {
            // `text-accent` measured 2.53:1 on the light-blue own bubble after
            // the sent/received colour split — it was only ever verified
            // against surface backgrounds. `accent-vivid` is the foreground
            // role and clears AA on every incoming bubble (5.33-7.27); on the
            // OWN bubble it still fails (3.85 light-blue), so the `.prose-own`
            // rule in TextMessageContent.vue / MixedMessageContent.vue drops it
            // to `inherit` there. `font-semibold` is what keeps the mention
            // distinguishable in that inherit case, where colour cannot.
            return `<span class="cursor-pointer font-semibold text-accent-vivid" data-uid="${escapeHtml(uid)}">@${escapeHtml(user.nickname)}</span>`
          }
          return `@${match.getMention()}`
        }
      }
    }
  })

  static md = (() => {
    const md = new MarkdownIt({
      // Peer message bodies reach a v-html sink (TextMessageContent.vue /
      // MixedMessageContent.vue); raw HTML must stay inert to prevent stored
      // XSS. Markdown syntax still renders — only literal HTML is escaped.
      html: false,
      breaks: true
    })

    const defaultRender =
      md.renderer.rules.link_open ||
      function (tokens, idx, options, env, self) {
        return self.renderToken(tokens, idx, options)
      }

    md.renderer.rules.link_open = function (tokens, idx, options, env, self) {
      tokens[idx].attrSet('target', '_blank')
      tokens[idx].attrSet('rel', 'noopener noreferrer')
      return defaultRender(tokens, idx, options, env, self)
    }

    // Add dir="auto" to block-level elements for per-paragraph RTL support.
    // This is applied at the <p>/<h1>-<h6>/<li> level (not the container)
    // to avoid WebKit layout bugs with dir="auto" + overflow:hidden + CSS Grid.
    const blockOpenTags = [
      'paragraph_open',
      'heading_open',
      'bullet_list_open',
      'ordered_list_open'
    ] as const
    for (const tag of blockOpenTags) {
      const prev =
        md.renderer.rules[tag] ||
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        function (tokens: any, idx: any, options: any, _env: any, self: any) {
          return self.renderToken(tokens, idx, options)
        }
      md.renderer.rules[tag] = function (tokens, idx, options, env, self) {
        tokens[idx].attrSet('dir', 'auto')
        return prev(tokens, idx, options, env, self)
      }
    }

    return md
  })()

  get html(): string {
    return TextMessage.autolinker.link(TextMessage.md.render(this.text))
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { message: text, reply } = raw
    this.text = text ?? ''
    this.translatedText = null
    this.replyId = typeof reply === 'string' ? reply : (reply?._id ?? null)
    this.urls = parseUrls(text)
  }

  static linkfy(text: string): string {
    try {
      return TextMessage.autolinker.link(text.replaceAll('\n', '<br>'))
    } catch (e) {
      console.error(e)
      return text
    }
  }
}

export class AIStreamingMessage extends Message {
  text: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { text } = raw
    this.text = text
  }
}

export class ImageMessage extends Message {
  images: IMImage[]
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    this.images = parseImages(raw)
  }
}

export class MixedMessage extends Message {
  text: string
  translatedText: string | null
  replyId: string | null
  urls: string[]
  images: IMImage[]

  get string(): string {
    const $ = cheerio.load(this.html)
    return $.text()
  }

  get html(): string {
    return TextMessage.autolinker.link(TextMessage.md.render(this.text))
  }

  previewString(): string {
    return this.string
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { message: text, reply } = raw
    this.text = text ?? ''
    this.translatedText = null
    this.replyId = typeof reply === 'string' ? reply : (reply?._id ?? null)
    this.images = parseImages(raw)
    this.urls = parseUrls(text)
  }
}

export class StickerMessage extends Message {
  stickerId: string
  stickerUrl: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { sticker, extra } = raw
    if (sticker) {
      if (isURL(sticker)) {
        this.stickerId = ''
        this.stickerUrl = sticker
      } else {
        this.stickerId = sticker
        this.stickerUrl = ''
      }
    } else {
      this.stickerId = ''
      this.stickerUrl = `https://stickershop.line-scdn.net/stickershop/v1/sticker/${extra.stickerId}/ios/sticker.png`
    }
  }
}

export class VideoMessage extends Message {
  video: IMVideo
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const {
      id,
      width,
      height,
      thumbnailUrl,
      originalUrl,
      duration,
      thumbnailFile,
      video
    } = raw
    if (video) {
      this.video = video
    } else {
      this.video = {
        id: id || originalUrl,
        width,
        height,
        thumbnailUrl,
        originalUrl,
        duration,
        thumbnailFile
      }
    }
  }
}
export enum TemplateMessageType {
  Buttons = 'buttons',
  Confirm = 'confirm',
  Carousel = 'carousel',
  ImageCarousel = 'image_carousel'
}
export class TemplateMessage extends Message {
  template: any // eslint-disable-line @typescript-eslint/no-explicit-any
  templateType: TemplateMessageType
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { template } = raw
    try {
      this.template =
        typeof template === 'object' ? template : JSON.parse(template)
      const { type } = this.template
      this.templateType = type
    } catch (e) {
      console.log(raw)
      console.error(e)
      this.template = {}
      this.templateType = TemplateMessageType.Buttons
    }
  }
}

export enum FlexMessageType {
  Bubble = 'bubble',
  Carousel = 'carousel'
}
export class FlexMessage extends Message {
  contents: any // eslint-disable-line @typescript-eslint/no-explicit-any
  flexType: FlexMessageType
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { contents } = raw
    try {
      this.contents =
        typeof contents === 'object' ? contents : JSON.parse(contents)
      const { type } = this.contents
      this.flexType = type
    } catch (e) {
      console.log(raw)
      console.error(e)
      this.contents = {}
      this.flexType = FlexMessageType.Bubble
    }
  }
}

export class LocationMessage extends Message {
  address: string
  latitude: number
  longitude: number
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { message, latitude, longitude } = raw
    this.address = message
    this.latitude = latitude
    this.longitude = longitude
  }
}
export class SystemMessage extends Message {
  members: User[]
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    switch (raw.messageType) {
      case MessageType.AddMember:
        this.members = [new User(raw.member)]
        break
      case MessageType.DeleteMember:
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        this.members = raw.extra.members.map((member: any) => new User(member))
        break
      case MessageType.AddMembers:
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        this.members = raw.extra.invitees.map((member: any) => new User(member))
        break
      default:
        this.members = []
    }
  }

  _string(uid: string, users: { [uid: string]: User }): string {
    const senderNickname = users[this.senderId]?.nickname ?? ''
    const memberNames = this.members.map((member) => member.nickname).join(', ')
    switch (this.type) {
      case MessageType.AddMember:
      case MessageType.AddMembers:
        return i18n.global.t('someoneInvited', [senderNickname, memberNames])
      case MessageType.DeleteMember:
        return i18n.global.t('someoneKicked', [senderNickname, memberNames])
      default:
        return super._string(uid, users)
    }
  }
}

export class FileMessage extends Message {
  url: string
  mimeType: string
  fileName: string
  bytes: number
  fileExtension: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { originalUrl, extra } = raw
    this.url = originalUrl
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let parsed: any = {}
    try {
      parsed =
        typeof extra === 'object' && extra
          ? extra
          : extra
            ? JSON.parse(extra)
            : {}
    } catch {
      /* malformed extra */
    }
    this.mimeType = parsed.mimeType
    this.fileName = parsed.fileName
    this.bytes = parsed.bytes
    this.fileExtension = parsed.fileExtension
  }
}
// {\"bytes\":115972,\"fileExtension\":\"m4a\",\"mimeType\":\"audio\\/m4a\",\"fileName\":\"20230128_175426\"}
export class AudioMessage extends Message {
  url: string
  mimeType: string
  fileName: string
  bytes: number
  fileExtension: string
  duration: number
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(raw: any) {
    super(raw)
    const { originalUrl, extra, duration } = raw
    this.url = originalUrl
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let parsed: any = {}
    try {
      parsed =
        typeof extra === 'object' && extra
          ? extra
          : extra
            ? JSON.parse(extra)
            : {}
    } catch {
      /* malformed extra */
    }
    const { mimeType, fileName, bytes, fileExtension } = parsed
    this.mimeType = mimeType
    this.fileName = fileName
    this.bytes = bytes
    this.fileExtension = fileExtension
    this.duration = duration
  }
}
