<script setup lang="ts">
import { computed } from 'vue'
import FlexMessageBubbleComponent from '../components/FlexMessageBubbleComponent.vue'
import { FlexMessage } from './../../../classes/message'

// Mirror FlexMessageBoxComponent's untrusted-payload guard: a carousel renders
// one bubble per entry, so an oversized/non-array `contents` would otherwise
// render unbounded bubbles (or iterate a non-array) straight from the payload.
const MAX_FLEX_CAROUSEL_CHILDREN = 200
const props = defineProps<{ message: FlexMessage }>()
const bubbles = computed(() =>
  Array.isArray(props.message.contents.contents)
    ? props.message.contents.contents.slice(0, MAX_FLEX_CAROUSEL_CHILDREN)
    : []
)
</script>

<template>
  <div class="flex items-start gap-2 overflow-auto">
    <flex-message-bubble-component
      v-for="(content, index) in bubbles"
      :key="index"
      :content="content"
      :room-id="message.roomId"
      :is-incoming="message.isIncoming"
    />
  </div>
</template>

<style scoped></style>
