<script setup lang="ts">
import { computed } from 'vue'
import { AdvancedMarker, GoogleMap } from 'vue3-google-map'
import { getConfig } from '../runtime/config'
import { LocationMessage } from './../classes/message'
import { GOOGLE_MAP_DEMO_MAP_ID } from './../constants'
const props = defineProps<{ message: LocationMessage }>()
const config = getConfig()
const apiKey = config.mapApiKey
const mapId = config.mapId || GOOGLE_MAP_DEMO_MAP_ID
const center = computed(() => ({
  lat: props.message.latitude,
  lng: props.message.longitude
}))
const isIncoming = computed(() => props.message.isIncoming)
const navigateToGoogleMap = () => {
  // address is server/peer-supplied: encode it so it can't inject extra query
  // params, and open with noopener/noreferrer.
  window.open(
    `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
      props.message.address
    )}`,
    '_blank',
    'noopener,noreferrer'
  )
}
</script>

<template>
  <div
    class="relative -mx-4 -my-2.5 flex cursor-pointer flex-col"
    @click="navigateToGoogleMap"
  >
    <google-map
      :api-key="apiKey"
      :center="center"
      :zoom="15"
      :disable-default-ui="true"
      :map-id="mapId"
      class="h-[150px] w-[250px] sm:h-[200px] sm:w-[300px]"
    >
      <AdvancedMarker :options="{ position: center }" />
    </google-map>

    <!-- The address acts as a link. `text-accent-vivid` can fall below 4.5:1
         against a customer-derived `bg-message-own`,
         so on an own bubble it inherits the bubble's verified
         `text-message-own-content` colour instead; the underline is retained
         either way, so it still reads as a link. Same rule as the prose links
         in TextMessageContent.vue / MixedMessageContent.vue. -->
    <div
      class="w-[250px] p-2 text-base underline sm:w-[300px]"
      :class="isIncoming ? 'text-accent-vivid' : 'text-inherit'"
    >
      {{ message.address }}
    </div>
    <div class="absolute inset-0" />
  </div>
</template>

<style scoped>
/* No radius here on purpose. The bubble wrapper in MessageCell.vue owns
   `overflow-hidden` plus the bubble's actual corner classes (20px, squared
   to 6px on the corners that face a grouped run) and clips this element's
   content to that exact shape as long as the content fully fills the
   bubble's padding box — see the `-mx-4 -my-2.5` above, which now matches
   the wrapper's `px-4 py-2.5`. A fixed radius here previously hard-coded
   12px top corners regardless of the bubble's real corner (20px standalone,
   6px squared), and the map didn't reach the padding edge (stale `-mx-3
   -my-2` from before the wrapper moved to `px-4 py-2.5`), so its own square
   corner showed inside the bubble's rounded frame. `overflow: hidden` is
   kept: vue3-google-map's internal canvas can paint slightly past its
   container, and this clips that regardless of corner shape. */
:deep(.mapdiv) > div > div {
  overflow: hidden;
}
</style>
