<script setup lang="ts">
import { Folder as FolderIcon, Pencil, Plus, Trash2 } from 'lucide-vue-next'
import { computed } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Folder from '../../classes/folder'
import { useImkitModal as useModal } from '../../composables/useImkitModal'
import { useImkitStore } from '../../stores/imkit'
import DeleteFolderConfirmModal from '../DeleteFolderConfirmModal.vue'
import UpdateFolderModal from './UpdateFolderModal.vue'

const vfm = useVfm()
const imkit = useImkitStore()

// imkit.sortedFolderIds is the server's folders-meta array order, i.e.
// creation order — the list here intentionally does not re-sort it.
const sortedFolders = computed(() =>
  imkit.sortedFolderIds
    .map((id: string) => imkit.folders[id])
    .filter((folder: Folder): folder is Folder => !!folder)
)

// The pencil and trash open the SAME UpdateFolderModal / DeleteFolderConfirmModal
// already used elsewhere (FolderCell's former menu, RoomList's create-folder
// flow) rather than acting inline, so rename/delete keep a single
// implementation. Both of those modals close the whole vfm stack on
// confirm/cancel (`vfm.closeAll()`), which also dismisses this dialog — the
// same trade-off AddToFolderModal's own "create new folder" row already
// makes. Deleting a folder still goes through DeleteFolderConfirmModal's own
// confirmation step, so the destructive action is never one click.
const editFolder = (folder: Folder) => {
  const { open } = useModal({
    component: UpdateFolderModal,
    attrs: { folderId: folder.id }
  })
  open()
}

const removeFolder = (folder: Folder) => {
  const { open } = useModal({
    component: DeleteFolderConfirmModal,
    attrs: { folder }
  })
  open()
}

const createFolder = () => {
  const { open } = useModal({
    component: UpdateFolderModal,
    attrs: { folderId: '' }
  })
  open()
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg border border-border p-5 flex min-h-0 max-h-[calc(var(--imkit-viewport-height)_-_2rem)] w-[calc(100vw-2rem)] max-w-[360px] flex-col gap-3 overflow-hidden shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
    aria-labelledby="manage-folders-title"
    aria-describedby="manage-folders-explanation"
  >
    <h2 id="manage-folders-title" class="text-xl font-semibold text-content">
      {{ $t('manageFoldersTitle') }}
    </h2>
    <p id="manage-folders-explanation" class="text-xs text-content-muted">
      {{ $t('manageFoldersExplain') }}
    </p>
    <div class="flex min-h-0 flex-col rounded-md border border-border">
      <div data-testid="manage-folders-list" class="min-h-0 overflow-y-auto">
        <div
          v-for="folder in sortedFolders"
          :key="folder.id"
          data-testid="manage-folder-row"
          class="flex items-center gap-3 border-b border-border p-2.5 last:border-b-0"
        >
          <!-- Rounded-square glyph, matching FolderCell.vue's grid treatment
             (accent-subtle fill, muted icon) at a smaller size appropriate
             to a list row rather than the room-list's 50px column. -->
          <span
            class="flex h-10 w-10 shrink-0 items-center justify-center rounded-md bg-accent-subtle text-content-muted"
          >
            <FolderIcon :size="18" />
          </span>
          <span class="flex min-w-0 grow flex-col">
            <span class="truncate text-base text-content">{{
              folder.name
            }}</span>
            <span class="text-xs text-content-muted">
              {{
                folder.roomIds.length
                  ? $t('numberOfChatroom', folder.roomIds.length)
                  : $t('no-chatroom')
              }}
            </span>
          </span>
          <div class="flex shrink-0 items-center gap-1">
            <button
              type="button"
              data-testid="manage-folder-edit"
              class="flex h-8 w-8 cursor-pointer items-center justify-center rounded-md text-content-muted transition-colors hover:bg-surface-hover"
              :aria-label="$t('editFolder')"
              @click="editFolder(folder)"
            >
              <Pencil :size="16" />
            </button>
            <button
              type="button"
              data-testid="manage-folder-delete"
              class="flex h-8 w-8 cursor-pointer items-center justify-center rounded-md text-content-muted transition-colors hover:bg-surface-hover"
              :aria-label="$t('delete')"
              @click="removeFolder(folder)"
            >
              <Trash2 :size="16" />
            </button>
          </div>
        </div>
      </div>
      <button
        type="button"
        data-testid="manage-folder-create"
        class="flex shrink-0 cursor-pointer items-center gap-2 border-t border-border p-2.5 text-left text-accent-vivid transition-colors hover:bg-surface-hover"
        @click="createFolder"
      >
        <Plus :size="16" />
        <span class="text-base font-medium">{{
          $t('createNewFolderPrompt')
        }}</span>
      </button>
    </div>
    <div class="mt-1 flex items-center justify-end">
      <button
        type="button"
        data-testid="manage-folders-done"
        class="inline-flex h-10 cursor-pointer items-center justify-center rounded-md bg-accent px-4 text-base font-medium text-white transition-colors hover:bg-accent-hover"
        @click="vfm.closeAll()"
      >
        {{ $t('done') }}
      </button>
    </div>
  </vue-final-modal>
</template>
