import { onUnmounted, ref, watch, type Ref } from 'vue'

// How long to keep re-measuring after tracking starts, expressed in animation
// frames (~600ms at 60fps). A software keyboard retracts over an animation and
// a webview re-lays the page out in stages while it does, so the anchor has to
// follow every intermediate frame — a single measurement, or one taken on the
// resize event alone, lands mid-animation and sticks there.
const SETTLE_FRAMES = 40

const isSameRect = (a: DOMRect | null, b: DOMRect) =>
  !!a &&
  a.top === b.top &&
  a.left === b.left &&
  a.width === b.width &&
  a.height === b.height

/**
 * Keeps `target`'s viewport rect up to date while `active` is true.
 *
 * Callers that paint a fixed-position clone of an element (the mobile
 * long-press overlay) cannot use a single `getBoundingClientRect()` snapshot:
 * anything that reflows the page afterwards leaves the clone stranded at the
 * old coordinates. In an iOS webview, blurring the composer collapses the
 * software keyboard, which resizes the layout viewport and reflows the chat a
 * few frames after the menu opens (issue #18).
 */
export const useTrackedElementRect = (
  target: Ref<HTMLElement | null>,
  active: Ref<boolean>
) => {
  const rect = ref<DOMRect | null>(null)

  let framesLeft = 0
  let frameId: number | null = null

  const canAnimate =
    typeof window !== 'undefined' &&
    typeof window.requestAnimationFrame === 'function'

  const measure = () => {
    const element = target.value
    if (!element) return
    const next = element.getBoundingClientRect()
    if (isSameRect(rect.value, next)) return
    rect.value = next
  }

  const tick = () => {
    frameId = null
    measure()
    if (framesLeft > 0) {
      framesLeft -= 1
      frameId = window.requestAnimationFrame(tick)
    }
  }

  // Every listener restarts the settle window rather than measuring once:
  // resize and scroll fire before the list has finished re-anchoring itself,
  // so the frame that carries the final position always comes later.
  const restartSettle = () => {
    measure()
    if (!canAnimate) return
    framesLeft = SETTLE_FRAMES
    if (frameId === null) frameId = window.requestAnimationFrame(tick)
  }

  // Scroll events do not bubble, so the list's own scroller is only reachable
  // from the capture phase on window.
  const SCROLL_OPTIONS = { capture: true, passive: true } as const

  const bind = () => {
    if (typeof window === 'undefined') return
    window.addEventListener('resize', restartSettle)
    window.addEventListener('scroll', restartSettle, SCROLL_OPTIONS)
    window.visualViewport?.addEventListener('resize', restartSettle)
    window.visualViewport?.addEventListener('scroll', restartSettle)
  }

  const unbind = () => {
    if (typeof window === 'undefined') return
    window.removeEventListener('resize', restartSettle)
    window.removeEventListener('scroll', restartSettle, SCROLL_OPTIONS)
    window.visualViewport?.removeEventListener('resize', restartSettle)
    window.visualViewport?.removeEventListener('scroll', restartSettle)
  }

  const stop = () => {
    if (frameId !== null && canAnimate) {
      window.cancelAnimationFrame(frameId)
    }
    frameId = null
    framesLeft = 0
    unbind()
  }

  watch(
    active,
    (isActive) => {
      stop()
      if (!isActive) {
        rect.value = null
        return
      }
      bind()
      restartSettle()
    },
    // Same-tick snapshot so the first rect is the pre-collapse position.
    // Callers set `active` before blurring the composer.
    { flush: 'sync' }
  )

  onUnmounted(stop)

  return { rect }
}
